        if (v.target !== null) tally[v.target] = (tally[v.target] ?? 0) + weight;
      }
      const top = Object.entries(tally).sort(([a, x], [b, y]) => y - x || Number(a) - Number(b)),
        leaders = top.filter(([, n]) => n === top[0]?.[1]).map(([id]) => Number(id));
      exileTarget = leaders.length === 1 ? leaders[0]! : null;
      check(equal(p.votes, ballots) && equal(p.tally, tally) && p.target === exileTarget);
      if (exileRound === 1 && leaders.length > 1) exileCandidates = leaders;
    }
    if (e.type === "exile_pk_started") {
      check(exileRound === 1 && exileCandidates && equal(p.candidates, exileCandidates));
      exileRound = 2;
    }
    if (e.type === "sheriff_badge_transferred" || e.type === "sheriff_badge_destroyed") {
      const from = p.fromId ?? p.playerId ?? p.sheriffId;
      check(from === sheriff && !alive.has(sheriff!));
      const d: RecordedDecision | undefined = rows("sheriff_badge_choice", sheriff!)[0];
      const c = d ? call(d) : null;
      const target: unknown = c?.name === "choose_badge_successor" ? c.args.target_id : null;
      destroyed.add(Number(from));
      if (e.type === "sheriff_badge_transferred") {
        check(typeof p.toId === "number" && alive.has(p.toId) && target === p.toId);
        sheriff = p.toId;
      } else {
        check(target === null || !alive.has(Number(target)));
        destroyed.add(Number(from));
        sheriff = null;
      }
    }
    if (e.type === "last_words_granted" || e.type === "last_words_spoken") {
      check(typeof p.playerId === "number");
      const f = deathFacts.get(p.playerId),
        key = `${day}/${p.playerId}`;
      check(f && f.day === day && wordsEligible(f));
      if (e.type === "last_words_granted") {
        check(!granted.has(key));
        granted.add(key);
      } else {
        const d = rows("last_words", p.playerId)[0],
          c = d && call(d);
        check(
          granted.has(key) &&
            !spoken.has(key) &&
            c?.name === "speak" &&
            p.text === sanitizeSpeechText(c.args.text),
        );
        spoken.add(key);
      }
    }
    if (e.type === "day_speech") {
      check(typeof p.actorId === "number" && alive.has(p.actorId));
      const candidates = r.decisions.filter(
        (d) =>
          d.day === day &&
          d.actorId === p.actorId &&
          [
            "day_speech",
            "sheriff_campaign_speech",
            "sheriff_pk_speech",
            "exile_pk_speech",
          ].includes(d.stage) &&
          !publicSpeeches.has(d) &&
          d.openedAtEventCount! <= i,
      );
      check(candidates.length === 1);
      const d = candidates[0],
        c = d && call(d);
      check(c?.name === "speak" && p.text === sanitizeSpeechText(c.args.text));
      publicSpeeches.add(d!);
    }
    if (e.type === "night_resolved") {
      check(!announcedNights.has(day));
      announcedNights.add(day);
      check(consumedNight.has(day) || Object.keys(validateNativeNight()).length === 0);
      check(equal(p.deaths, Object.keys(validateNativeNight()).map(Number)));
      publicDeaths(p.deaths, true);
    }
    if (e.type === "additional_deaths") publicDeaths(p.deaths);
    if (e.type === "voted_out") {
      check(phase === Phase.Voting && typeof p.target === "number" && alive.has(p.target));
    }
    if (e.type === "game_over") {
      check(pendingPublic.size === 0 && pendingLinks.size === 0 && phase === Phase.GameOver);
      const remaining = [...alive].map((id) => roster.get(id)!);
      const wolf = remaining.filter((p) => p.camp === Camp.Wolf),
        villagers = remaining.filter((p) => p.role === Role.Villager),
        gods = remaining.filter((p) => p.camp === Camp.Good && p.role !== Role.Villager),
        winner =
          wolf.length === 0
            ? Camp.Good
            : gods.length === 0 || villagers.length === 0
              ? Camp.Wolf
              : null;
      const winners = [...roster.values()]
        .filter((p) => p.camp === winner)
        .map((p) => p.id)
        .sort((a, b) => a - b);
      check(
        equal(p.outcome, {
          kind: "victory",
          primary: { kind: "faction", faction: winner, winningPlayerIds: winners },
          additional: [],
          winningPlayerIds: winners,
        }),
      );
      check(
        winner !== null &&
          p.winner === winner &&
          p.reason ===
            (winner === Camp.Good ? "all_wolves_eliminated" : "slaughter_side_completed"),
      );
    }
    save(i + 1);
  }
  for (const cp of r.checkpoints) checkpoint(cp);
  for (const d of r.decisions) {
    check(
      equal(d.request.context.visible_events, fragrantFeedAt(r, d.openedAtEventCount!, d.actorId)),
    );
    const v = at.get(d.openedAtEventCount!);
    check(
      v &&
        d.actorId === d.request.actorId &&
        d.day === d.request.context.day &&
        d.stage === d.request.context.stage &&
        d.request.phase === v.phase &&
        d.day === v.day &&
        d.openedAfterSettlement <= (d.settleOrder ?? Number.MAX_SAFE_INTEGER),
    );
    if (["fragrant_bind", "pair_inspection"].includes(d.stage)) {
      const bind = d.stage === "fragrant_bind",
        actor = bind ? phantomId : seerId,
        tool = bind ? "bind_fragrant_pair" : "check_pair",
        ctx = d.request.context;
      check(
        d.actorId === actor &&
          v.phase === Phase.Night &&
          v.alive.has(actor) &&
          v.state.nights.at(-1)?.day === d.day &&
          v.state.nights.at(-1)?.status === "open" &&
          !(bind
            ? v.state.nights.at(-1)?.bindCommitted || v.state.fragrant.trigger
            : v.state.nights.at(-1)?.pairCommitted) &&
          equal(d.request.allowedTools, [tool]) &&
          ctx.allow_fallback === false &&
          ctx.action_failure_policy === "error" &&
          equal(ctx.turn_constraints.required_any_tools, [tool]) &&
          ctx.turn_constraints.min_valid_actions === 1 &&
          ctx.turn_constraints.max_valid_actions === 1 &&
          equal(
            bind ? ctx.fragrant_pair_candidates : ctx.pair_check_candidates,
            [...v.alive].sort((a, b) => a - b),
          ),
      );
      check(rows(d.stage, d.actorId, d.day).length === 1);
      if (!bind) {
        const prefix = r.events.slice(0, d.openedAtEventCount),
          start = openings.get(d.day)!;
        check(
          !start.has(phantomId) || v.state.fragrant.trigger || v.state.nights.at(-1)?.bindCommitted,
        );
        check(
          !start.has(witchId) ||
            prefix.some(
              (e) =>
                ["witch_potion_used", "witch_potion_skipped"].includes(e.type) &&
                e.payload.actorId === witchId &&
                at.get(r.events.indexOf(e) + 1)?.day === d.day,
            ),
        );
        check(
          !start.has(guardId) ||
            call(rows("guard", guardId, d.day)[0]!) === null ||
            prefix.some(
              (e) => e.type === "guard_applied" && at.get(r.events.indexOf(e) + 1)?.day === d.day,
            ),
        );
        const earlier = r.decisions.filter(
          (q) =>
            q.day === d.day &&
            ["fragrant_bind", "guard", "witch", "wolf_vote"].includes(q.stage) &&
            q.settleOrder !== undefined,
        );
        check(earlier.every((q) => q.settleOrder! <= d.openedAfterSettlement));
      }
      check(bind ? ctx.ability_id === undefined : ctx.ability_id === "native:pair_check");
      if (d.outcome.kind === "action") check(completed.has(d));
    }
    if (d.request.allowedTools.some((t) => t === "speak_to_wolves" || t === "kill_vote"))
      check(
        d.request.context.allow_fallback === false &&
          d.request.context.action_failure_policy === "error",
      );
    if (
      v.phase === Phase.Night &&
      [
        "fragrant_bind",
        "pair_inspection",
        "wolf_discussion",
        "wolf_vote",
        "guard",
        "witch",
      ].includes(d.stage)
    ) {
      const start = openings.get(d.day);
      check(start && v.state.nights.at(-1)?.day === d.day);
      if (start.has(phantomId))
        check(
          r.events
            .slice(0, d.openedAtEventCount)
            .some((e) => e.type === "fragrant_night_notified" && e.payload.day === d.day),
        );
      if (d.stage !== "fragrant_bind" && start.has(phantomId) && !v.state.fragrant.trigger)
        check(v.state.nights.at(-1)?.bindCommitted);
    }
    if (d.request.allowedTools.includes("speak_to_wolves")) check(d.actorId !== phantomId);
    if (d.request.allowedTools.includes("self_destruct")) check(d.actorId !== phantomId);
    if (d.request.allowedTools.includes("kill_vote"))
      check(
        wolves.includes(d.actorId) ||
          (d.actorId === phantomId && v.state.nights.at(-1)?.knife === true),
      );
  }
  const settledOrders = r.decisions
    .filter((d) => d.settleOrder !== undefined)
    .map((d) => d.settleOrder!)
    .sort((a, b) => a - b);
  check(settledOrders.every((n, i) => n === i + 1));
  check(r.checkpoints.every((cp, i) => cp.cycle === i));
  if (r.finalized) {
    const last = r.checkpoints.at(-1)!;
    check(
      last.eventCount === r.events.length &&
        last.decisionCount === r.decisions.length &&
        last.operationCount === r.operations.length,
    );
  }
  // 归档成功完成 finalize 时，游标须与领域操作一致。
  if (r.finalized) {
    let previous = 0;
    for (const o of r.operations) {
      check(
        o.event_count !== undefined &&
          o.event_count >= previous &&
          o.event_count <= r.events.length,
      );
      previous = o.event_count;
    }
    for (const o of r.operations.filter((o) => o.op.startsWith("fragrant_"))) {
      check(o.status === "ok");
      if (o.op === "fragrant_night_opened") {
        check(
          o.scope === "phase_pipeline" &&
            o.phase === Phase.Night &&
            o.actor_id === undefined &&
            o.output,
        );
        const output = o.output,
          di = output.day,
          ev = r.events.findIndex(
            (e) => e.type === "fragrant_night_opened" && e.payload.day === di,
          ),
          notice = r.events.find(
            (e) => e.type === "fragrant_night_notified" && e.payload.day === di,
          );
        check(
          ev >= 0 &&
            equal(output, {
              policy: FRAGRANT_PAIR_POLICY,
              day: di,
              notice: notice
                ? { actorId: notice.payload.actorId, day: di, known: notice.payload.known }
                : null,
              knowledgeDrawCount: di === 1 ? 1 : 0,
            }) &&
            o.event_count! >= ev + 1 &&
            o.event_count! <= ev + 3,
        );
      } else {
        check(
          [
            "fragrant_pair_chosen",
            "fragrant_pair_inspected",
            "fragrant_wave_committed",
            "fragrant_link_triggered",
          ].includes(o.op),
        );
        const choice = o.op === "fragrant_pair_chosen" || o.op === "fragrant_pair_inspected";
        check(
          o.scope === (choice ? "phase_pipeline" : "resolution") &&
            (!choice || o.phase === Phase.Night) &&
            o.phase !== Phase.GameOver &&
            o.actor_id ===
              (choice ? (o.op === "fragrant_pair_chosen" ? phantomId : seerId) : undefined),
        );
        const ei = r.events.findIndex((e) => e.type === o.op && equal(e.payload, o.output));
        check(
          ei >= 0 &&
            o.event_count! >= ei + 1 &&
            o.event_count! <= ei + 2 &&
            o.phase === at.get(ei + 1)?.phase,
        );
      }
    }
    for (const cp of r.checkpoints) {
      check(cp.operationCount! <= r.operations.length);
      check(
        cp.operationCount === r.operations.filter((o) => o.event_count! <= cp.eventCount).length,
      );
    }
    for (const [day, start] of openings) {
      const cp = r.checkpoints.find((cp) => cp.cycle === day);
      if (!cp?.complete) continue;
      const n = r.operations.filter(
        (o) => o.op === "fragrant_night_opened" && o.output?.day === day,
      );
      check(n.length === 1 && n[0]!.output?.knowledgeDrawCount === (day === 1 ? 1 : 0));
      check(!start.has(phantomId) || noticeDays.has(day));
    }
    for (let i = 0; i < r.events.length; i++) {
      const e = r.events[i]!;
      if (
        ![
          "fragrant_pair_chosen",
          "fragrant_pair_inspected",
          "fragrant_wave_committed",
          "fragrant_link_triggered",
        ].includes(e.type)
      )
        continue;
      const ops = r.operations.filter((o) => o.op === e.type && equal(o.output, e.payload));
      const cp = r.checkpoints.find((cp) => cp.eventCount >= i + 1);
      if (cp?.complete) check(ops.length === 1);
      else check(ops.length <= 1);
      for (const o of ops) check(o.event_count! >= i + 1 && o.event_count! <= i + 2);
    }
  }
  check(pendingLinks.size === 0 || r.checkpoints.at(-1)?.complete === false);
}

/**
 * Responsibility: read fragrant-pair facts at a recorded publication position.
 * Input: a reproduction archive and causal prefix.
 * Output: detached historical feed data.
 * Boundary: never grants live disclosure or writes relation state.
 */
import { FRAGRANT_PAIR_EVENT_TYPES } from "@ai-werewolf-arena/game-contract/facts/fragrant-pair-seer";
import type { ReproductionRecord } from "./reproduction";
/** Literal finite-board authorization/projection oracle, independent of the engine feed. */
export function fragrantFeedAt(r: ReproductionRecord, cursor: number, actor: number): unknown[] {
  const publicTypes = new Set([
      "phase_changed",
      "day_speech",
      "night_resolved",
      "additional_deaths",
      "vote_summary",
      "voted_out",
      "game_over",
      "wolf_self_destruct",
      "last_words_granted",
      "last_words_spoken",
      "sheriff_nomination_summary",
      "sheriff_withdraw_summary",
      "sheriff_candidates_finalized",
      "sheriff_pk_started",
      "exile_pk_started",
      "sheriff_vote_summary",
      "sheriff_badge_transferred",
      "sheriff_badge_destroyed",
      "sheriff_direction_chosen",
    ]),
    packTypes = new Set([
      "wolf_tactical_order",
      "wolf_discussion",
      "wolf_discussion_ended",
      "wolf_kill_vote_cast",
    ]);
  const out: unknown[] = [];
  for (const e of r.events.slice(0, cursor)) {
    const p = e.payload;
    let payload: Record<string, unknown> | null = null,
      type = e.type;
    if ((FRAGRANT_PAIR_EVENT_TYPES as readonly string[]).includes(type)) {
      if (
        ["fragrant_pair_chosen", "fragrant_pair_inspected", "fragrant_night_notified"].includes(
          type,
        ) &&
        p.actorId === actor &&
        e.audience?.length === 1 &&
        e.audience[0] === actor
      )
        payload = structuredClone(p);
    } else if (type === "hunter_shot") {
      type = "player_shot";
      payload = { actorId: p.hunterId, targetId: p.targetId };
    } else if (packTypes.has(type)) {
      if (e.audience?.includes(actor)) payload = structuredClone(p);
    } else if (["witch_potion_used", "witch_potion_skipped", "guard_applied"].includes(type)) {
      if (p.actorId === actor) payload = structuredClone(p);
    } else if (publicTypes.has(type)) {
      if (type === "vote_summary") {
        const { tally: _tally, ...rest } = p;
        payload = structuredClone(rest);
      } else payload = structuredClone(p);
    }
    if (payload) out.push({ seq: out.length + 1, type, payload });
  }
  return out;
}

/**
 * 负责独立审核雾鸦致死、延期与请求因果。输入为归档配置、决定、事实与 checkpoint；
 * 输出为原一致性结果或明确拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import {
  check,
  equal,
  ids,
  exact,
  mistDraw,
  validateMistRavenRequests,
  selectedMistBlast,
} from "./mist_raven_requests";
import { createMistSheriffEvidence } from "./mist_raven_sheriff_record";
import { validateMistRavenFeeds } from "./mist_raven_feed_record";
import { isMistRavenPreset } from "../verification/board-support";
import {
  MIST_RAVEN_EVENT_TYPES,
  readMistRavenFact,
} from "@ai-werewolf-arena/game-contract/facts/mist-raven";
import { Camp, Phase, Role } from "@ai-werewolf-arena/game-contract";
import type { RecordedCheckpoint, ReproductionRecord } from "./reproduction";

type AlchemistLedger = {
  policy: "awa_mist_raven_v1";
  mistRemaining: number;
  healRemaining: number;
  mistHistory: Array<{ day: number; targetIds: number[] | null }>;
  healHistory: Array<{ day: number; targetId: number | null }>;
};
type RavenLedger = {
  policy: "awa_mist_raven_v1";
  awakenedDay: number | null;
  knownTeammateIds: number[];
  extraRemaining: number;
  extraHistory: Array<{ day: number; targetId: number | null }>;
};
type NightLedger = {
  day: number;
  start: number[];
  mistStock: number;
  snakeStock: number;
  extraStock: number;
  awake: boolean;
  unsealExpected: boolean;
  known: number[];
  unsealSeen: boolean;
  delay: boolean;
  mistSeen: boolean;
  ravenSeen: boolean;
  circle: number[] | null;
  dream: number | null;
  consecutive: boolean;
  dreamSeen: boolean;
  seerSeen: boolean;
  order: number[] | null;
  votes: Map<number, number | null>;
  drawSeen: boolean;
  knife: number | null;
  extra: number | null;
  snakeSeen: boolean;
  healed: number | null;
  settled: boolean;
  blast: boolean;
  damage: { deaths: number[]; death_sources: Record<number, string[]> } | null;
  reasons: Array<{
    actorId: number;
    targetId: number;
    day: number;
    reason: "linked" | "consecutive";
  }>;
  reasonsSeen: number;
  direction: "clockwise" | "counter_clockwise";
  publishedDay: boolean;
};
const privateFields = [
  "mist_candidates",
  "wolf_kill_candidates",
  "snake_target",
  "snake_candidates",
  "raven_candidates",
];
const nativeEvents = new Set<string>([
  ...MIST_RAVEN_EVENT_TYPES,
  "god_private_game_info",
  "phase_changed",
  "game_over",
  "dream_applied",
  "dream_death",
  "seer_checked",
  "day_speech",
  "last_words_granted",
  "last_words_spoken",
  "night_resolved",
  "wolf_tactical_order",
  "wolf_discussion",
  "wolf_discussion_ended",
  "wolf_kill_vote_cast",
  "wolf_self_destruct",
  "vote_cast",
  "vote_summary",
  "voted_out",
  "idiot_revealed",
  "exile_pk_started",
  "sheriff_candidate_declared",
  "sheriff_nomination_summary",
  "sheriff_withdraw_summary",
  "sheriff_candidates_finalized",
  "sheriff_vote_cast",
  "sheriff_vote_summary",
  "sheriff_pk_started",
  "sheriff_elected",
  "sheriff_direction_chosen",
  "sheriff_badge_transferred",
  "sheriff_badge_destroyed",
]);
/** 独立归档账本不查询生产 frame、目标选择器或伤害系统。 */
export function validateMistRavenRecord(record: ReproductionRecord): void {
  const board = record.metadata.normalizedBoard;
  const owns = board.roleSetups.some(
    (p) => (p.role === Role.Alchemist || p.role === Role.RavenClawWolf) && p.count > 0,
  );
  const artifacts =
    record.events.some((e) => (MIST_RAVEN_EVENT_TYPES as readonly string[]).includes(e.type)) ||
    record.decisions.some(
      (d) =>
        ["alchemist_mist", "alchemist_snake", "raven_knife"].includes(d.stage) ||
        privateFields.some((k) => Object.hasOwn(d.request.context, k)) ||
        d.request.allowedTools.some((t) => ["cast_mist", "use_snake", "raven_knife"].includes(t)),
    ) ||
    record.checkpoints.some((c) =>
      c.players.some(
        (p) =>
          Object.hasOwn(p.privateState, "alchemist") || Object.hasOwn(p.privateState, "ravenClaw"),
      ),
    );
  if (!owns) {
    check(
      !board.mistRaven &&
        !artifacts &&
        !record.metadata.players.some(
          (p) => p.role === Role.Alchemist || p.role === Role.RavenClawWolf,
        ),
    );
    return;
  }
  check(isMistRavenPreset(board) && !record.metadata.faultPlan && !record.metadata.initialDeal);
  const roster = new Map(record.metadata.players.map((p) => [p.id, p]));
  check(
    equal(
      [...roster.keys()].sort((a, b) => a - b),
      Array.from({ length: 12 }, (_, i) => i + 1),
    ),
  );
  const counts: Array<[Role, number]> = [
    [Role.Wolf, 3],
    [Role.RavenClawWolf, 1],
    [Role.Villager, 4],
    [Role.Alchemist, 1],
    [Role.Seer, 1],
    [Role.Dreamer, 1],
    [Role.Idiot, 1],
  ];
  for (const [role, count] of counts)
    check([...roster.values()].filter((p) => p.role === role).length === count);
  for (const p of roster.values())
    check(p.camp === ([Role.Wolf, Role.RavenClawWolf].includes(p.role) ? Camp.Wolf : Camp.Good));
  const actor = (role: Role) => [...roster.values()].find((p) => p.role === role)!.id;
  const alchemist = actor(Role.Alchemist),
    raven = actor(Role.RavenClawWolf),
    dreamer = actor(Role.Dreamer),
    seer = actor(Role.Seer),
    idiot = actor(Role.Idiot);
  const isWolf = (id: number) => roster.get(id)?.camp === Camp.Wolf;
  const alive = new Set(roster.keys());
  const election = createMistSheriffEvidence(record);
  const votes = new Map([...roster.keys()].map((id) => [id, { weight: 1, canVote: true }]));
  const badges = new Map<number, RecordedCheckpoint["players"][number]["badge"]>(
    [...roster.keys()].map((id) => [id, { isSheriff: false, destroyed: false, voteWeight: 1.5 }]),
  );
  let result: RecordedCheckpoint["snapshot"]["result"] = null;
  const a: AlchemistLedger = {
    policy: "awa_mist_raven_v1",
    mistRemaining: 1,
    healRemaining: 1,
    mistHistory: [],
    healHistory: [],
  };
  const r: RavenLedger = {
    policy: "awa_mist_raven_v1",
    awakenedDay: null,
    knownTeammateIds: [],
    extraRemaining: 1,
    extraHistory: [],
  };
  const dreamHistory: Array<{ day: number; targetId: number }> = [];
  const seerHistory: Array<{
    targetId: number;
    isWerewolf: boolean;
    result: { kind: "camp"; camp: Camp };
  }> = [];
  let idiotRevealed = false,
    day = 1,
    phase: Phase = Phase.Night,
