          ),
      );
      n.votes.set(p.actorId, p.abstain ? null : (p.targetId as number));
    }
    if (e.type === "wolf_self_destruct") {
      const n = requireNight();
      const selected = selectedMistBlast(
        record.decisions.filter(
          (d) =>
            d.day === n.day &&
            d.stage === p.window &&
            alive.has(d.actorId) &&
            roster.get(d.actorId)?.role === Role.Wolf,
        ),
        undefined,
        [...alive].filter((id) => roster.get(id)?.role === Role.Wolf),
      );
      check(
        ((phase === Phase.Day &&
          ["on_pre_election", "on_daybreak", "on_per_speech_gap"].includes(p.window as string)) ||
          (phase === Phase.Voting && p.window === "on_pre_vote" && n.settled)) &&
          !n.blast &&
          typeof p.wolfId === "number" &&
          roster.get(p.wolfId)?.role === Role.Wolf &&
          selected?.actorId === p.wolfId &&
          alive.has(p.wolfId),
      );
      n.blast = true;
      alive.delete(p.wolfId);
    }
    if (e.type === "night_resolved") {
      const n = requireNight();
      check(phase === Phase.Day && !n.settled && (!n.delay || n.snakeSeen));
      resolveKnife(n);
      n.damage = finalDamage(n);
      check(equal(p.deaths, n.damage.deaths));
      n.settled = true;
      for (const id of n.damage.deaths) alive.delete(id);
    }
    if (e.type === "dream_death") {
      const n = requireNight();
      check(n.settled && equal(p, n.reasons[n.reasonsSeen]));
      n.reasonsSeen++;
    }
    if (e.type === "voted_out") {
      check(
        phase === Phase.Voting &&
          exileTallied &&
          p.target === exileExpected &&
          typeof p.target === "number" &&
          alive.has(p.target),
      );
      alive.delete(p.target);
    }
    if (e.type === "vote_cast") {
      check(
        phase === Phase.Voting &&
          typeof p.actorId === "number" &&
          p.actorId ===
            [...alive].filter((id) => votes.get(id)!.canVote && !exileCandidates?.includes(id))[
              exileBallots.length
            ],
      );
      const expected = exileBallot(p.actorId);
      check(equal(p, expected));
      const { fallback: _fallback, ...publicVote } = expected;
      exileBallots.push(publicVote);
    }
    if (e.type === "vote_summary") {
      check(
        phase === Phase.Voting &&
          (p.round ?? 1) === exileRound &&
          equal(p.votes, exileBallots) &&
          exileBallots.length ===
            [...alive].filter((id) => votes.get(id)!.canVote && !exileCandidates?.includes(id))
              .length,
      );
      const tally: Record<number, number> = {};
      for (const v of exileBallots)
        if (!v.abstain && v.targetId !== null)
          tally[v.targetId] = (tally[v.targetId] ?? 0) + v.weight;
      const max = Math.max(0, ...Object.values(tally)),
        top = Object.entries(tally)
          .filter(([, v]) => v === max && max > 0)
          .map(([id]) => Number(id))
          .sort((a, b) => a - b);
      check(equal(p.tally, tally));
      exileExpected = top.length === 1 ? top[0]! : null;
      check(p.target === exileExpected);
      exileTallied = true;
      if (exileRound === 1 && top.length > 1) exileCandidates = top;
    }
    if (e.type === "exile_pk_started") {
      check(
        phase === Phase.Voting &&
          exileRound === 1 &&
          exileTallied &&
          exileCandidates !== null &&
          equal(p.candidates, exileCandidates),
      );
      exileRound = 2;
      exileBallots = [];
      exileTallied = false;
      exileExpected = null;
    }
    if (e.type === "idiot_revealed") {
      check(
        phase === Phase.Voting &&
          exileTallied &&
          exileExpected === idiot &&
          p.targetId === idiot &&
          !idiotRevealed &&
          alive.has(idiot),
      );
      idiotRevealed = true;
      votes.set(idiot, { weight: 0, canVote: false });
    }
    if (e.type === "sheriff_elected") {
      check(
        sheriff === null &&
          p.winnerId === election.winner &&
          typeof p.winnerId === "number" &&
          alive.has(p.winnerId),
      );
      sheriff = p.winnerId;
      for (const id of alive) {
        badges.set(id, {
          isSheriff: id === sheriff,
          destroyed: false,
          voteWeight: 1.5,
          handoffPolicy: "awa_holder_choice_v1",
        });
        const vote = votes.get(id)!;
        if (vote.canVote) vote.weight = id === sheriff ? 1.5 : 1;
      }
    }
    if (e.type === "sheriff_direction_chosen") {
      const n = requireNight();
      check(
        phase === Phase.Day &&
          p.sheriffId === sheriff &&
          sheriff !== null &&
          alive.has(sheriff) &&
          ["clockwise", "counter_clockwise"].includes(p.direction as string),
      );
      const list = rows(day, "sheriff_choose_direction", sheriff);
      check(list.length === 1 && list[0]!.outcome.kind === "action");
      const outcome = list[0]!.outcome;
      const chosen =
        outcome.kind === "action" &&
        outcome.action?.name === "choose_direction" &&
        ["clockwise", "counter_clockwise"].includes(outcome.action.args.direction)
          ? outcome.action.args.direction
          : "clockwise";
      check(p.direction === chosen);
      n.direction = chosen;
    }
    if (e.type === "sheriff_badge_transferred") {
      check(
        p.fromId === sheriff &&
          typeof p.toId === "number" &&
          alive.has(p.toId) &&
          badgeChoice(sheriff!, p.reason) === p.toId,
      );
      const from = sheriff!;
      const source = badges.get(from)!;
      source.isSheriff = false;
      source.destroyed = true;
      votes.get(from)!.weight = votes.get(from)!.canVote ? 1 : 0;
      badges.set(p.toId, {
        isSheriff: true,
        destroyed: false,
        voteWeight: 1.5,
        ...(source.handoffPolicy ? { handoffPolicy: source.handoffPolicy } : {}),
      });
      votes.get(p.toId)!.weight = 1.5;
      sheriff = p.toId;
    }
    if (e.type === "sheriff_badge_destroyed") {
      check(p.targetId === sheriff && badgeChoice(sheriff!, p.reason) === null);
      const from = sheriff!;
      badges.get(from)!.isSheriff = false;
      badges.get(from)!.destroyed = true;
      votes.get(from)!.weight = votes.get(from)!.canVote ? 1 : 0;
      sheriff = null;
    }
    if (e.type === "game_over") {
      check(requireNight().settled && phase === Phase.GameOver && result === null);
      const expected = [...alive].every((id) => !isWolf(id))
        ? Camp.Good
        : ![...alive].some((id) => roster.get(id)!.role === Role.Villager) ||
            ![...alive].some((id) =>
              [Role.Alchemist, Role.Seer, Role.Dreamer, Role.Idiot].includes(roster.get(id)!.role),
            )
          ? Camp.Wolf
          : null;
      check(
        p.reason === "max_days_reached"
          ? p.winner === null && day >= record.metadata.maxDays
          : p.winner === expected && expected !== null,
      );
      if (expected !== null && p.reason !== "max_days_reached") {
        const winners = [...roster.values()]
          .filter((p) => p.camp === expected)
          .map((p) => p.id)
          .sort((a, b) => a - b);
        check(
          p.reason ===
            (expected === Camp.Good ? "all_wolves_eliminated" : "slaughter_side_completed") &&
            equal(p.outcome, {
              kind: "victory",
              primary: { kind: "faction", faction: expected, winningPlayerIds: winners },
              additional: [],
              winningPlayerIds: winners,
            }),
        );
      }
      result = p as unknown as NonNullable<typeof result>;
    }
    for (const cp of checkpoints.get(index + 1) ?? []) checkpoint(cp);
  }
  for (const cp of record.checkpoints) check(cp.eventCount <= record.events.length);
  validateMistRavenRequests({
    record,
    nights,
    alive,
    alchemistState: a,
    ravenState: r,
    actors: { alchemist, raven, dreamer, seer },
  });
  validateMistRavenFeeds(record, nights);
  const resolved = [...nights.values()].filter((n) => n.settled),
    ops = record.operations.filter(
      (o) => o.scope === "resolution" && o.op === "night_damage_resolved",
    );
  if (record.finalized || ops.length) {
    check(ops.length === resolved.length);
    for (let i = 0; i < ops.length; i++)
      check(equal(ops[i]!.output, resolved[i]!.damage) && ops[i]!.phase === Phase.Night);
  }
}

/**
 * 负责独立审核雾鸦请求阶段、工具和可见历史。输入为归档配置、决定、事实与 checkpoint；
 * 输出为原一致性结果或明确拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import { Role, Camp, Phase } from "@ai-werewolf-arena/game-contract";
import type { RecordedDecision, ReproductionRecord } from "./reproduction";
const strictStages = {
  alchemist_mist: "cast_mist",
  dreamer: "dream",
  wolf_discussion: "speak_to_wolves",
  wolf_vote: "kill_vote",
  raven_knife: "raven_knife",
  seer: "check_identity",
  alchemist_snake: "use_snake",
} as const;
const privateFields = [
  "mist_candidates",
  "wolf_kill_candidates",
  "snake_target",
  "snake_candidates",
  "raven_candidates",
];
const stageTools: Record<string, string[]> = {
  ...Object.fromEntries(Object.entries(strictStages).map(([stage, tool]) => [stage, [tool]])),
  on_pre_election: ["self_destruct"],
  on_daybreak: ["self_destruct"],
  on_per_speech_gap: ["self_destruct"],
  on_pre_vote: ["self_destruct"],
  sheriff_nomination: ["run_for_sheriff"],
  sheriff_withdraw: ["run_for_sheriff"],
  sheriff_campaign_speech: ["speak"],
  sheriff_pk_speech: ["speak"],
  sheriff_vote: ["vote_for_sheriff"],
  sheriff_pk_vote: ["vote_for_sheriff"],
  sheriff_choose_direction: ["choose_direction"],
  sheriff_badge_choice: ["choose_badge_successor"],
  day_speech: ["speak"],
  last_words: ["speak"],
  voting: ["vote"],
  exile_pk_speech: ["speak"],
  exile_pk_vote: ["vote"],
};
export function check(value: unknown): asserts value {
  if (!value) throw new Error("reproduction_mist_raven_invalid");
}
/** 只按归档选择：同一批 intent 中仅应用最低 ID 的那一项。 */
export function selectedMistBlast(
  decisions: readonly RecordedDecision[],
  receiverOpenedAfter?: number,
  eligibleActors?: readonly number[],
): RecordedDecision | undefined {
  const choices = decisions.filter(
    (d) =>
      d.outcome.kind === "action" &&
      d.outcome.action?.name === "self_destruct" &&
      d.outcome.action.args.confirm === true &&
      (receiverOpenedAfter === undefined ||
        (d.settleOrder !== undefined && d.settleOrder <= receiverOpenedAfter)),
  );
  const first = choices[0];
  if (!first) return;
  check(
    choices.every(
      (d) =>
        d.day === first.day &&
        d.stage === first.stage &&
        d.turn === first.turn &&
        d.openedAfterSettlement === first.openedAfterSettlement &&
        d.request.actionWindow === first.request.actionWindow,
    ),
  );
  check(new Set(choices.map((d) => d.actorId)).size === choices.length);
  const turns = new Map<number, number>(),
    batch: RecordedDecision[] = [];
  for (const d of decisions.filter((d) => d.day === first.day && d.stage === first.stage)) {
    const turn = (turns.get(d.actorId) ?? 0) + 1;
    turns.set(d.actorId, turn);
    check(d.turn === turn && d.request.actionWindow === d.stage);
    if (turn === first.turn) batch.push(d);
  }
  check(
    batch.every(
      (d) =>
        d.openedAfterSettlement === first.openedAfterSettlement &&
        d.outcome.kind === "action" &&
        d.settleOrder !== undefined &&
        (receiverOpenedAfter === undefined || d.settleOrder <= receiverOpenedAfter),
    ),
  );
  if (eligibleActors)
    check(
      equal(
        batch.map((d) => d.actorId).sort((a, b) => a - b),
        [...eligibleActors].sort((a, b) => a - b),
      ),
    );
  return choices.reduce((a, b) => (a.actorId < b.actorId ? a : b));
}
export function equal(a: unknown, b: unknown): boolean {
  const stable = (v: unknown): unknown =>
    Array.isArray(v)
      ? v.map(stable)
      : v && typeof v === "object"
        ? Object.fromEntries(
            Object.entries(v)
              .sort(([a], [b]) => a.localeCompare(b))
              .map(([k, x]) => [k, stable(x)]),
          )
        : v;
  return JSON.stringify(stable(a)) === JSON.stringify(stable(b));
}
export function ids(value: unknown): value is number[] {
  return (
    Array.isArray(value) &&
    value.every((v) => Number.isSafeInteger(v) && v > 0 && v <= 12) &&
    new Set(value).size === value.length
  );
}
export function exact(value: unknown, keys: string[]): value is Record<string, unknown> {
  return (
    !!value &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length === keys.length &&
    keys.every((k) => Object.hasOwn(value, k))
  );
}
export function mistDraw(seed: string, path: readonly string[]): number {
  const input = JSON.stringify([seed, ...path]);
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++)
    hash = Math.imul(hash ^ input.charCodeAt(i), 0x01000193) >>> 0;
  let value = (hash + 0x6d2b79f5) >>> 0;
  value = Math.imul(value ^ (value >>> 15), value | 1);
  value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
  return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
}

export interface MistNightRequestEvidence {
  start: number[];
  mistStock: number;
  snakeStock: number;
  extraStock: number;
  awake: boolean;
  delay: boolean;
  circle: number[] | null;
  publishedDay: boolean;
}
export function validateMistRavenRequests(input: {
  record: ReproductionRecord;
  nights: ReadonlyMap<number, MistNightRequestEvidence>;
  alive: ReadonlySet<number>;
  alchemistState: { mistRemaining: number; healRemaining: number };
  ravenState: { awakenedDay: number | null; extraRemaining: number };
  actors: { alchemist: number; raven: number; dreamer: number; seer: number };
}): void {
  const {
    record,
    nights,
    alive,
    alchemistState,
    ravenState,
    actors: { alchemist, raven, dreamer, seer },
  } = input;
  const lastNight = Math.max(0, ...nights.keys()),
    roster = new Map(record.metadata.players.map((p) => [p.id, p]));
  const failure = record.checkpoints.at(-1),
    last = record.decisions.at(-1);
  const tailStart = [...alive],
    tailWolves = tailStart.filter((id) => roster.get(id)!.camp === Camp.Wolf);
  const inferred = new Map<
    number,
    {
      start: number[];
      mistStock: number;
      snakeStock: number;
      extraStock: number;
      awake: boolean;
      delay: boolean;
      circle: number[] | null;
      publishedDay: boolean;
    }
  >();
  for (const [day, n] of nights) inferred.set(day, n);
  const tail = lastNight + 1;
  if (record.decisions.some((d) => d.day === tail)) {
    check(!failure?.snapshot.gameOver);
    inferred.set(tail, {
      start: tailStart,
      mistStock: alchemistState.mistRemaining,
      snakeStock: alchemistState.healRemaining,
      extraStock: ravenState.extraRemaining,
      awake:
        ravenState.awakenedDay !== null || (tailStart.includes(raven) && tailWolves.length < 3),
      delay: tailStart.includes(alchemist) && alchemistState.healRemaining === 1,
      circle: null,
      publishedDay: false,
    });
  }
  const rank: Record<string, number> = {
    alchemist_mist: 10,
    dreamer: 20,
    wolf_discussion: 30,
    wolf_vote: 40,
    raven_knife: 50,
    seer: 60,
  };
  const valid = new Map<RecordedDecision, boolean>();
  const getCall = (d: RecordedDecision) => (d.outcome.kind === "action" ? d.outcome.action : null);
  const rows = (day: number, stage: string, id?: number) =>
    record.decisions.filter(
      (d) => d.day === day && d.stage === stage && (id === undefined || d.actorId === id),
    );
  for (const [day, n] of inferred) {
    const mist = rows(day, "alchemist_mist")[0],
      call = mist && getCall(mist);
    const provisional = call?.name === "cast_mist" ? call.args.target_ids : null;
    const circle = n.circle ?? provisional;
    const pack = n.start.filter(
      (id) => roster.get(id)!.role === Role.Wolf || (id === raven && n.awake),
    );
    for (const d of record.decisions.filter((d) => d.day === day)) {
      check(
        Object.hasOwn(stageTools, d.stage) && equal(d.request.allowedTools, stageTools[d.stage]),
      );
      check(
        d.request.actorId === d.actorId &&
          d.request.context.day === day &&
          d.request.context.stage === d.stage,
      );
      const c = d.request.context;
      if (!Object.hasOwn(strictStages, d.stage)) {
        check(n.start.includes(d.actorId));
        const voting = ["on_pre_vote", "voting", "exile_pk_vote", "exile_pk_speech"].includes(
          d.stage,
        );
        check(
          ["last_words", "sheriff_badge_choice"].includes(d.stage)
            ? [Phase.Day, Phase.Voting].includes(d.request.phase)
            : d.request.phase === (voting ? Phase.Voting : Phase.Day),
        );
        if (d.stage.startsWith("on_")) {
          check(
            roster.get(d.actorId)!.role === Role.Wolf &&
              (d.stage !== "on_pre_election" || day === 1) &&
              !c.visible_events.some(
                (e) =>
                  (e.type === "night_resolved" &&
                    Array.isArray(e.payload.deaths) &&
                    e.payload.deaths.includes(d.actorId)) ||
                  (e.type === "wolf_self_destruct" && e.payload.wolfId === d.actorId),
              ),
          );
        }
      }
      for (const field of privateFields) {
        const present = Object.hasOwn(c, field),
          belongs =
            field === "mist_candidates"
              ? d.stage === "alchemist_mist"
              : field === "wolf_kill_candidates"
                ? ["wolf_discussion", "wolf_vote"].includes(d.stage)
                : field === "raven_candidates"
                  ? d.stage === "raven_knife"
                  : d.stage === "alchemist_snake";
        check(present === belongs);
      }
      check(c.wolf_target === undefined && c.wolf_targets === undefined);
      const tool = strictStages[d.stage as keyof typeof strictStages];
      if (!tool) continue;
      const expectedActor = ["alchemist_mist", "alchemist_snake"].includes(d.stage)
        ? alchemist
        : d.stage === "raven_knife"
          ? raven
          : d.stage === "dreamer"
            ? dreamer
            : d.stage === "seer"
              ? seer
              : null;
      check(expectedActor === null || d.actorId === expectedActor);
      check(
        d.request.phase === (d.stage === "alchemist_snake" ? Phase.Day : Phase.Night) &&
          equal(d.request.allowedTools, [tool]) &&
          c.allow_fallback === false &&
          c.action_failure_policy === "error" &&
          c.turn_constraints.min_valid_actions === 1 &&
          c.turn_constraints.max_valid_actions === 1 &&
          equal(c.turn_constraints.required_any_tools, [tool]),
      );
      check(
        d.stage === "wolf_discussion"
          ? d.turn >= 1 && d.turn <= 3 && c.round === d.turn && c.max_rounds === 3
          : d.turn === 1,
      );
      if (d.stage === "alchemist_mist")
        check(
          n.start.includes(alchemist) &&
            n.mistStock === 1 &&
            n.start.length >= 3 &&
            equal(c.mist_candidates, n.start),
        );
      if (d.stage === "raven_knife")
        check(
          n.start.includes(raven) &&
            n.awake &&
            n.extraStock === 1 &&
            equal(
              c.raven_candidates,
              n.start.filter((id) => id !== raven),
            ),
        );
      if (d.stage === "dreamer")
        check(n.start.includes(dreamer) && c.ability_id === "native:dream");
      if (d.stage === "seer") check(n.start.includes(seer) && c.ability_id === "native:seer_check");
      if (d.stage === "alchemist_snake") check(n.delay);
      if (d.stage === "wolf_discussion" || d.stage === "wolf_vote")
        check(pack.includes(d.actorId) && equal(c.wolf_kill_candidates, circle ?? n.start));
      const a = getCall(d);
      let accepted = false;
      if (a?.name === tool) {
        const args = a.args as unknown as Record<string, unknown>;
        if (tool === "cast_mist")
          accepted =
            exact(args, ["target_ids"]) &&
            (args.target_ids === null ||
              (ids(args.target_ids) &&
                args.target_ids.length === 3 &&
                args.target_ids.every((id) => n.start.includes(id))));
        else if (tool === "speak_to_wolves")
          accepted =
            exact(args, ["text", "end_chat"]) &&
            typeof args.text === "string" &&
            typeof args.end_chat === "boolean";
        else if (tool === "kill_vote")
          accepted =
            exact(args, ["target_id", "abstain"]) &&
            typeof args.abstain === "boolean" &&
            (args.abstain
              ? args.target_id === null
              : typeof args.target_id === "number" && (circle ?? n.start).includes(args.target_id));
        else if (tool === "use_snake")
          accepted =
            exact(args, ["target_id"]) &&
            (args.target_id === null ||
              (typeof args.target_id === "number" &&
                c.snake_candidates?.includes(args.target_id) === true));
        else
          accepted =
            exact(args, ["target_id"]) &&
            ((tool === "raven_knife" && args.target_id === null) ||
              (typeof args.target_id === "number" &&
                args.target_id !== d.actorId &&
                n.start.includes(args.target_id)));
      }
      valid.set(d, accepted && d.settleOrder !== undefined);
      // 非法原始回复仅能作为显式终态失败 checkpoint 中的证据；
      // 它们不能成为已提交事实，也不能授权后续请求。
      if (d.outcome.kind === "action" && !accepted)
        check(d === last && failure?.complete === false && failure.snapshot.day === day);
    }
    const chain = record.decisions.filter(
      (d) => d.day === day && d.request.phase === Phase.Night && Object.hasOwn(rank, d.stage),
    );
    for (let i = 0; i < chain.length; i++) {
      const d = chain[i]!;
      if (i > 0) {
        const previous = chain[i - 1]!;
        check(
          valid.get(previous) &&
            previous.settleOrder !== undefined &&
            d.openedAfterSettlement >= previous.settleOrder &&
            rank[d.stage]! >= rank[previous.stage]!,
        );
      }
    }
    const dayRows = record.decisions.filter(
      (d) => d.day === day && d.request.phase !== Phase.Night,
    );
    const progress = Math.max(
      0,
      ...chain.map((d) => rank[d.stage]!),
      dayRows.length || n.publishedDay ? 70 : 0,
    );
    const one = (stage: string, id: number, eligible: boolean) => {
      const list = rows(day, stage, id),
        stageRank = rank[stage]!;
      check(list.length <= 1 && (eligible || list.length === 0));
      if (eligible && progress >= stageRank) check(list.length === 1);
      if (eligible && progress > stageRank) check(valid.get(list[0]!));
    };
    one(
      "alchemist_mist",
      alchemist,
      n.start.includes(alchemist) && n.mistStock === 1 && n.start.length >= 3,
    );
    one("dreamer", dreamer, n.start.includes(dreamer) && n.start.length > 1);
    one(
      "raven_knife",
      raven,
      n.start.includes(raven) && n.awake && n.extraStock === 1 && n.start.length > 1,
    );
    one("seer", seer, n.start.includes(seer) && n.start.length > 1);
    for (const id of pack) {
      const chats = rows(day, "wolf_discussion", id),
        votes = rows(day, "wolf_vote", id);
      check(chats.length <= 3 && votes.length <= 1);
      for (let i = 0; i < chats.length; i++) check(chats[i]!.turn === i + 1);
      if (progress > 30) {
        check(chats.length >= 1 && chats.every((d) => valid.get(d)));
        const a = getCall(chats.at(-1)!);
        check(a?.name === "speak_to_wolves" && (a.args.end_chat || chats.length === 3));
      }
      if (progress > 40) check(votes.length === 1 && valid.get(votes[0]!));
    }
    if (dayRows.length && chain.length) {
      const finished = chain.at(-1)!;
      check(
        valid.get(finished) &&
          finished.settleOrder !== undefined &&
          dayRows[0]!.openedAfterSettlement >= finished.settleOrder,
      );
    }
    const snakes = rows(day, "alchemist_snake");
    check(snakes.length <= 1 && (n.delay || snakes.length === 0));
    if (snakes.length) {
      const d = snakes[0]!,
        votes = rows(day, "wolf_vote");
      check(votes.length === pack.length && votes.every((d) => valid.get(d)));
      const tally = new Map<number, number>();
      for (const v of votes) {
        const a = getCall(v);
        check(a?.name === "kill_vote");
        if (!a.args.abstain && a.args.target_id !== null)
          tally.set(a.args.target_id, (tally.get(a.args.target_id) ?? 0) + 1);
      }
      let knife: number | null = null;
      if (tally.size) {
        const max = Math.max(...tally.values());
        knife = Math.min(...[...tally].filter(([, v]) => v === max).map(([id]) => id));
      } else if (circle !== null) {
        check(circle.length === 3 && pack.length > 0);
        knife =
          circle[
            Math.floor(
              mistDraw(record.metadata.random.seed, [
                ...record.metadata.random.path,
                "night",
                `day:${day}:mist-knife`,
              ]) * circle.length,
            )
          ]!;
      }
      const blasts = record.decisions.filter((b) => b.day === day && b.stage.startsWith("on_"));
      const blast = selectedMistBlast(
        blasts,
        d.openedAfterSettlement,
        n.start.filter((id) => roster.get(id)?.role === Role.Wolf),
      );
      for (const intent of blasts)
        check(roster.get(intent.actorId)?.role === Role.Wolf && n.start.includes(intent.actorId));
      if (blast) {
        const b = getCall(blast);
        check(
          roster.get(blast.actorId)?.role === Role.Wolf &&
            n.start.includes(blast.actorId) &&
            b?.name === "self_destruct" &&
            b.args.confirm === true &&
            blast.request.actionWindow !== "on_pre_vote",
        );
      }
      const living = n.start.filter((id) => id !== blast?.actorId),
        legal =
          knife !== null && living.includes(knife) && (day === 1 || knife !== alchemist)
            ? [knife]
            : [];
      check(
        d.request.context.snake_target === knife &&
          equal(d.request.context.snake_candidates, legal),
      );
      if (!blast) {
        const speeches = rows(day, "day_speech");
        check(
          equal(
            speeches.map((s) => s.actorId).sort((a, b) => a - b),
            [...living].sort((a, b) => a - b),
          ) &&
            speeches.every(
              (s) => s.settleOrder !== undefined && s.settleOrder <= d.openedAfterSettlement,
            ),
        );
      }
    }
  }
  check(record.decisions.every((d) => inferred.has(d.day)));
}

/**
 * 负责独立审核雾鸦历史位置上的原玩家知识。输入为归档配置、决定、事实与 checkpoint；
 * 输出为脱离的历史知情数据或原拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import {
  MIST_RAVEN_EVENT_TYPES,
  readMistRavenFact,
} from "@ai-werewolf-arena/game-contract/facts/mist-raven";
import { Camp, Phase, Role } from "@ai-werewolf-arena/game-contract";
import type { RecordedDecision, RecordedGameEvent, ReproductionRecord } from "./reproduction";
import {
  check,
  equal,
  exact,
  ids,
  mistDraw,
  selectedMistBlast,
  type MistNightRequestEvidence,
} from "./mist_raven_requests";
import { createMistSheriffEvidence } from "./mist_raven_sheriff_record";
import { sanitizeSpeechText } from "../utils/speech_text";

// 归档校验预期与实际可见性 registry、玩家投影实现相互独立。
const publicTypes = new Set([
  "phase_changed",
  "day_speech",
  "night_resolved",
  "vote_summary",
  "voted_out",
  "game_over",
  "wolf_self_destruct",
  "idiot_revealed",
  "last_words_granted",
  "last_words_spoken",
  "sheriff_nomination_summary",
  "sheriff_withdraw_summary",
  "sheriff_candidates_finalized",
  "sheriff_pk_started",
  "exile_pk_started",
  "sheriff_vote_summary",
  "sheriff_badge_transferred",
  "sheriff_badge_destroyed",
  "sheriff_direction_chosen",
]);
const packTypes = new Set([
  "wolf_tactical_order",
  "wolf_discussion",
  "wolf_discussion_ended",
  "wolf_kill_vote_cast",
  "mist_knife_drawn",
]);
const ownTypes = new Set([
  "seer_checked",
  "dream_applied",
  ...MIST_RAVEN_EVENT_TYPES.filter((t) => t !== "mist_knife_drawn"),
]);
const nightStages = new Set([
  "alchemist_mist",
  "dreamer",
  "wolf_discussion",
  "wolf_vote",
  "raven_knife",
  "seer",
]);
type WireFact = { seq: number; type: string; payload: Record<string, unknown> };
const publicWireKeys: Record<string, string[]> = {
  phase_changed: ["day", "phase"],
  day_speech: ["actorId", "text"],
  night_resolved: ["deaths"],
  vote_summary: ["votes", "target", "round"],
  voted_out: ["target"],
  wolf_self_destruct: ["wolfId", "window"],
  idiot_revealed: ["targetId"],
  last_words_granted: ["playerId", "phase", "day"],
  last_words_spoken: ["playerId", "phase", "day", "text"],
  sheriff_nomination_summary: ["candidates"],
  sheriff_withdraw_summary: ["withdrawn"],
  sheriff_candidates_finalized: ["candidates"],
  sheriff_pk_started: ["candidates"],
  exile_pk_started: ["candidates"],
  sheriff_vote_summary: ["votes", "winnerId", "round"],
  sheriff_badge_transferred: ["fromId", "toId", "reason"],
  sheriff_badge_destroyed: ["targetId", "reason"],
  sheriff_direction_chosen: ["sheriffId", "direction"],
};

export function validateMistRavenFeeds(
  record: ReproductionRecord,
  nights: ReadonlyMap<number, MistNightRequestEvidence>,
): void {
  const roster = new Map(record.metadata.players.map((p) => [p.id, p]));
  const rows = (day: number, stages: readonly string[], actor?: number) =>
    record.decisions.filter(
      (d) =>
        d.day === day && stages.includes(d.stage) && (actor === undefined || d.actorId === actor),
    );
  const settled = (ds: RecordedDecision[]) =>
    Math.max(0, ...ds.map((d) => d.settleOrder ?? Infinity));
  const call = (d: RecordedDecision) => (d.outcome.kind === "action" ? d.outcome.action : null);
  const visible = (e: Pick<RecordedGameEvent, "type" | "payload" | "audience">, actor: number) => {
    if (publicTypes.has(e.type)) return true;
    if (ownTypes.has(e.type)) return e.payload.actorId === actor;
    return packTypes.has(e.type) && e.audience?.includes(actor) === true;
  };
  const payload = (e: Pick<RecordedGameEvent, "type" | "payload">) => {
    if (e.type !== "vote_summary") return e.payload;
    const { tally: _tally, ...p } = e.payload;
    return p;
  };
  const timeline: Array<{ event: RecordedGameEvent; day: number; release: number }> = [];
  let day = 1,
    release = 0;
  const consumedSpeech = new Set<RecordedDecision>();
  for (const event of record.events) {
    const p = event.payload,
      type = event.type;
    if (type === "phase_changed") {
      day = Number(p.day);
      if (p.phase === Phase.Night)
        release = Math.max(release, settled(record.decisions.filter((d) => d.day < day)));
      if (p.phase === Phase.Day) release = Math.max(release, settled(rows(day, [...nightStages])));
      if (p.phase === Phase.Voting)
        release = Math.max(
          release,
          settled(
            record.decisions.filter(
              (d) =>
                d.day === day &&
                d.request.phase === Phase.Day &&
                d.stage !== "sheriff_badge_choice",
            ),
          ),
        );
    }
    const stage =
      type === "alchemist_mist_chosen" || type === "alchemist_mist_skipped"
        ? "alchemist_mist"
        : type === "alchemist_snake_chosen"
          ? "alchemist_snake"
          : type === "raven_knife_chosen"
            ? "raven_knife"
            : type === "dream_applied"
              ? "dreamer"
              : type === "seer_checked"
                ? "seer"
                : type === "wolf_kill_vote_cast"
                  ? "wolf_vote"
                  : type === "sheriff_direction_chosen"
                    ? "sheriff_choose_direction"
                    : null;
    if (stage)
      release = Math.max(release, settled(rows(day, [stage], Number(p.actorId ?? p.sheriffId))));
    if (type === "wolf_discussion" || type === "wolf_discussion_ended")
      release = Math.max(
        release,
        settled(
          rows(day, ["wolf_discussion"], Number(p.actorId)).filter((d) => d.turn === p.round),
        ),
      );
    if (type === "day_speech") {
      const source = rows(
        day,
        ["day_speech", "sheriff_campaign_speech", "sheriff_pk_speech", "exile_pk_speech"],
        Number(p.actorId),
      ).find((d) => {
        const a = call(d);
        return (
          !consumedSpeech.has(d) &&
          a?.name === "speak" &&
          sanitizeSpeechText(a.args.text) === p.text
        );
      });
      if (source) {
        consumedSpeech.add(source);
        release = Math.max(release, source.settleOrder ?? Infinity);
      }
    }
    if (type === "last_words_spoken")
      release = Math.max(
        release,
        settled(
          rows(day, ["last_words"], Number(p.playerId)).filter((d) => d.request.phase === p.phase),
        ),
      );
    if (["sheriff_nomination_summary", "sheriff_candidates_finalized"].includes(type))
      release = Math.max(release, settled(rows(day, ["sheriff_nomination"])));
    if (type === "sheriff_withdraw_summary")
      release = Math.max(release, settled(rows(day, ["sheriff_withdraw"])));
    if (type === "sheriff_vote_summary")
      release = Math.max(
        release,
        settled(rows(day, [p.round === 2 ? "sheriff_pk_vote" : "sheriff_vote"])),
      );
    if (type === "vote_summary")
      release = Math.max(release, settled(rows(day, [p.round === 2 ? "exile_pk_vote" : "voting"])));
    if (type === "wolf_self_destruct")
      release = Math.max(release, settled(rows(day, [String(p.window)])));
    if (["sheriff_badge_transferred", "sheriff_badge_destroyed"].includes(type))
      release = Math.max(
        release,
        settled(rows(day, ["sheriff_badge_choice"], Number(p.fromId ?? p.targetId))),
      );
    if (["wolf_tactical_order", "raven_unsealed"].includes(type))
      release = Math.max(
        release,
        settled(rows(day, ["alchemist_mist", "dreamer"]).filter((d) => type !== "raven_unsealed")),
      );
    if (["raven_knife_skipped", "mist_knife_drawn"].includes(type))
      release = Math.max(release, settled(rows(day, ["wolf_vote"])));
    if (type === "night_resolved")
      release = Math.max(release, settled(rows(day, ["alchemist_snake"])));
    timeline.push({ event, day, release });
  }
  const previous = new Map<number, WireFact[]>();
  for (const d of record.decisions) {
    const feed = d.request.context.visible_events;
    check(feed.every((e, i) => exact(e, ["seq", "type", "payload"]) && e.seq === i + 1));
    const slots = new Set<string>();
    let feedDay = 0,
      phaseRank = -1;
    for (const e of feed) {
      const keys = publicWireKeys[e.type];
      if (keys) check(exact(e.payload, keys));
      if (e.type === "phase_changed") {
        const number = Number(e.payload.day),
          rank =
            e.payload.phase === Phase.Night
              ? 0
              : e.payload.phase === Phase.Day
                ? 1
                : e.payload.phase === Phase.Voting
                  ? 2
                  : 3;
        check(number >= feedDay && (number > feedDay || rank > phaseRank));
        feedDay = number;
        phaseRank = rank;
      }
      if (ownTypes.has(e.type) || packTypes.has(e.type)) {
        check(phaseRank === (e.type === "alchemist_snake_chosen" ? 1 : 0));
        if (e.payload.day !== undefined) check(e.payload.day === feedDay);
      }
      if (e.type === "day_speech") continue;
      const key = JSON.stringify([
        feedDay,
        e.type,
        e.payload.actorId ?? e.payload.fromId ?? e.payload.targetId ?? e.payload.playerId,
        e.type.startsWith("last_words") ? e.payload.phase : undefined,
        e.type === "phase_changed" ? e.payload.phase : undefined,
        e.type.startsWith("wolf_discussion")
          ? e.payload.round
          : e.type.endsWith("vote_summary")
            ? (e.payload.round ?? 1)
            : undefined,
      ]);
      check(!slots.has(key));
      slots.add(key);
    }
    const prior = previous.get(d.actorId) ?? [];
    check(feed.length >= prior.length && equal(feed.slice(0, prior.length), prior));
    previous.set(d.actorId, feed);
    validateElectionFeed(d);
    const opened = record.decisions.slice(0, record.decisions.indexOf(d) + 1);
    for (const words of opened.filter((x) => x.stage === "last_words")) {
      const granted = { playerId: words.actorId, phase: words.request.phase, day: words.day };
      check(feed.some((e) => e.type === "last_words_granted" && equal(e.payload, granted)));
      const a = call(words);
      if (
        words.settleOrder !== undefined &&
        words.settleOrder <= d.openedAfterSettlement &&
        a?.name === "speak"
      )
        check(
          feed.some(
            (e) =>
              e.type === "last_words_spoken" &&
              equal(e.payload, { ...granted, text: sanitizeSpeechText(a.args.text) }),
          ),
        );
    }
    for (let number = 1; number <= d.day; number++) {
      let current = 0;
      const speeches = feed.filter((e) => {
        if (e.type === "phase_changed") current = Number(e.payload.day);
        return current === number && e.type === "day_speech";
      });
      const sources = record.decisions
        .filter(
          (x) =>
            x.day === number &&
            [
              "day_speech",
              "sheriff_campaign_speech",
              "sheriff_pk_speech",
              "exile_pk_speech",
            ].includes(x.stage) &&
            x.settleOrder !== undefined &&
            x.settleOrder <= d.openedAfterSettlement,
        )
        .sort((a, b) => a.settleOrder! - b.settleOrder!)
        .flatMap((x) => {
          const a = call(x);
          return a?.name === "speak"
            ? [{ actorId: x.actorId, text: sanitizeSpeechText(a.args.text) }]
            : [];
        });
      check(
        equal(
          speeches.map((e) => e.payload),
          sources,
        ),
      );
    }
    const expected = timeline
      .filter(
        (t) =>
          visible(t.event, d.actorId) && t.day <= d.day && t.release <= d.openedAfterSettlement,
      )
      .map(({ event }, i) => ({ seq: i + 1, type: event.type, payload: payload(event) }));
    // checkpoint 只发表事件前缀；当前请求可能已经包含尚未归档的后续事件。
    check(feed.length >= expected.length && equal(feed.slice(0, expected.length), expected));
    if (record.finalized || record.checkpoints.some((c) => c.complete && c.cycle >= d.day))
      check(feed.length === expected.length);
    let tailDay = Number(
      [...expected].reverse().find((e) => e.type === "phase_changed")?.payload.day ?? 1,
    );
    let tailPhase: unknown =
      [...expected].reverse().find((e) => e.type === "phase_changed")?.payload.phase ?? Phase.Night;
    for (const e of feed.slice(expected.length)) {
      if (e.type === "phase_changed") {
        tailDay = Number(e.payload.day);
        tailPhase = e.payload.phase;
      }
      validateUnpublished(e, d, tailDay, tailPhase);
    }
    const lastPhase = [...feed].reverse().find((e) => e.type === "phase_changed")?.payload;
    check(lastPhase?.day === d.day && lastPhase.phase === d.request.phase);
  }

  function validateUnpublished(
    e: WireFact,
    d: RecordedDecision,
    factDay: number,
    factPhase: unknown,
  ): void {
    const p = e.payload,
      role = roster.get(d.actorId)!.role;
    check(publicTypes.has(e.type) || ownTypes.has(e.type) || packTypes.has(e.type));
    if (e.type === "phase_changed") {
      check(
        exact(p, ["day", "phase"]) &&
          Number.isSafeInteger(p.day) &&
          Number(p.day) <= d.day &&
          [Phase.Night, Phase.Day, Phase.Voting].includes(p.phase as Phase),
      );
      if (p.day === d.day)
        check(
          [Phase.Night, Phase.Day, Phase.Voting].indexOf(p.phase as Phase) <=
            [Phase.Night, Phase.Day, Phase.Voting].indexOf(d.request.phase),
        );
      return;
    }
    if (
      e.type === "night_resolved" ||
      (e.type.startsWith("sheriff_") && !e.type.startsWith("sheriff_badge"))
    )
      check(factPhase === Phase.Day);
    if (["vote_summary", "exile_pk_started", "voted_out", "idiot_revealed"].includes(e.type))
      check(factPhase === Phase.Voting);
    if (ownTypes.has(e.type)) check(p.actorId === d.actorId);
    if (packTypes.has(e.type)) {
      check(
        role === Role.Wolf ||
          (role === Role.RavenClawWolf &&
            d.request.context.visible_events.some(
              (x) => x.type === "raven_unsealed" && Number(x.payload.day) <= d.day,
            )),
      );
    }
    const source = (
      stages: string[],
      actor: number,
      predicate: (x: RecordedDecision) => boolean,
    ) => {
      const matches = rows(Number(p.day ?? factDay), stages, actor).filter(predicate);
      check(
        matches.length === 1 &&
          matches[0]!.settleOrder !== undefined &&
          matches[0]!.settleOrder! <= d.openedAfterSettlement,
      );
      return call(matches[0]!);
    };
    if ((MIST_RAVEN_EVENT_TYPES as readonly string[]).includes(e.type)) {
      check(readMistRavenFact(e.type, p) && Number(p.day) <= d.day);
      if (e.type === "alchemist_mist_skipped") {
        const n = nights.get(Number(p.day)),
          cp = record.checkpoints.at(-1)!.players.find((x) => x.id === d.actorId)!;
        const start =
          n?.start ??
          record.checkpoints
            .at(-1)!
            .players.filter((x) => x.alive)
            .map((x) => x.id);
        const stock =
          n?.mistStock ?? (cp.privateState.alchemist as { mistRemaining: number }).mistRemaining;
        check(
          role === Role.Alchemist &&
            rows(Number(p.day), ["alchemist_mist"]).length === 0 &&
            p.reason ===
              (!start.includes(d.actorId) ? "dead" : stock === 0 ? "spent" : "no_targets") &&
            (!start.includes(d.actorId) || stock === 0 || start.length < 3),
        );
      } else if (e.type === "alchemist_mist_chosen") {
        const a = source(["alchemist_mist"], d.actorId, () => true);
        check(
          role === Role.Alchemist &&
            a?.name === "cast_mist" &&
            equal(a.args.target_ids, p.targetIds),
        );
      } else if (e.type === "alchemist_snake_chosen" || e.type === "raven_knife_chosen") {
        const stage = e.type === "alchemist_snake_chosen" ? "alchemist_snake" : "raven_knife";
        const a = source([stage], d.actorId, () => true);
        check(
          a?.name === (stage === "alchemist_snake" ? "use_snake" : "raven_knife") &&
            a.args.target_id === p.targetId,
        );
      } else if (e.type === "raven_unsealed") {
        const n = nights.get(Number(p.day));
        const start =
          n?.start ??
          record.checkpoints
            .at(-1)!
            .players.filter((x) => x.alive)
            .map((x) => x.id);
        const wolves = start.filter((id) => roster.get(id)!.camp === Camp.Wolf);
        check(
          role === Role.RavenClawWolf &&
            wolves.length < 3 &&
            equal(
              p.knownTeammateIds,
              wolves.filter((id) => id !== d.actorId).sort((a, b) => a - b),
            ),
        );
      } else if (e.type === "raven_knife_skipped") {
        check(
          role === Role.RavenClawWolf &&
            (p.reason === "sealed"
              ? !nights.get(Number(p.day))?.awake &&
                record.checkpoints.at(-1)!.players.filter((x) => x.alive && x.camp === Camp.Wolf)
                  .length >= 3
              : record.decisions.some(
                  (x) =>
                    x.day < Number(p.day) &&
                    x.stage === "raven_knife" &&
                    call(x)?.name === "raven_knife" &&
                    call(x)!.args &&
                    (call(x)!.args as Record<string, unknown>).target_id !== null,
                )),
        );
      } else {
        const mist = rows(Number(p.day), ["alchemist_mist"])[0],
          a = mist && call(mist);
        const ballots = rows(Number(p.day), ["wolf_vote"]);
        check(
          a?.name === "cast_mist" &&
            ids(a.args.target_ids) &&
            ballots.length > 0 &&
            settled(ballots) <= d.openedAfterSettlement &&
            ballots.every((b) => {
              const action = call(b);
              return action?.name === "kill_vote" && action.args.abstain;
            }) &&
            equal(p.candidates, a.args.target_ids) &&
            p.targetId ===
              a.args.target_ids[
                Math.floor(
                  mistDraw(record.metadata.random.seed, [
                    ...record.metadata.random.path,
                    "night",
                    `day:${p.day}:mist-knife`,
                  ]) * a.args.target_ids.length,
                )
              ],
        );
      }
      return;
    }
    if (e.type === "dream_applied") {
      const a = source(["dreamer"], d.actorId, () => true);
      check(
        role === Role.Dreamer &&
          exact(p, ["actorId", "targetId", "day", "consecutive"]) &&
          a?.name === "dream" &&
          a.args.target_id === p.targetId &&
          typeof p.consecutive === "boolean",
      );
      const earlier = rows(Number(p.day) - 1, ["dreamer"], d.actorId)[0];
      const before = earlier && call(earlier);
      check(p.consecutive === (before?.name === "dream" && before.args.target_id === p.targetId));
      return;
    }
    if (e.type === "seer_checked") {
      const a = source(
        ["seer"],
        d.actorId,
        (x) => x.settleOrder !== undefined && x.settleOrder <= d.openedAfterSettlement,
      );
      check(
        role === Role.Seer &&
          exact(p, ["actorId", "targetId", "isWerewolf", "result"]) &&
          a?.name === "check_identity" &&
          a.args.target_id === p.targetId &&
          p.isWerewolf === (roster.get(Number(p.targetId))?.camp === Camp.Wolf) &&
          equal(p.result, { kind: "camp", camp: roster.get(Number(p.targetId))?.camp }),
      );
      return;
    }
    if (e.type === "wolf_tactical_order") {
      const n = nights.get(factDay),
        start =
          n?.start ??
          record.checkpoints
            .at(-1)!
            .players.filter((x) => x.alive)
            .map((x) => x.id),
        wolves = start.filter((id) => roster.get(id)!.camp === Camp.Wolf),
        awake =
          n?.awake ??
          (wolves.length < 3 ||
            d.request.context.visible_events.some(
              (x) => x.type === "raven_unsealed" && Number(x.payload.day) <= factDay,
            )),
        pack = start.filter(
          (id) =>
            roster.get(id)!.role === Role.Wolf ||
            (roster.get(id)!.role === Role.RavenClawWolf && awake),
        );
      check(
        exact(p, ["order"]) &&
          ids(p.order) &&
          p.order.includes(d.actorId) &&
          equal(
            [...p.order].sort((a, b) => a - b),
            pack.sort((a, b) => a - b),
          ),
      );
      return;
    }
    if (e.type === "wolf_discussion" || e.type === "wolf_discussion_ended") {
      const a = source(["wolf_discussion"], Number(p.actorId), (x) => x.turn === p.round);
      check(
        a?.name === "speak_to_wolves" &&
          (e.type.endsWith("ended")
            ? a.args.end_chat &&
              p.reason === sanitizeSpeechText(a.args.text) &&
              exact(p, ["actorId", "reason", "round"])
            : !a.args.end_chat &&
              p.text === sanitizeSpeechText(a.args.text) &&
              p.endChat === false &&
              exact(p, ["actorId", "text", "endChat", "round"])),
      );
      return;
    }
    if (e.type === "wolf_kill_vote_cast") {
      const a = source(["wolf_vote"], Number(p.actorId), () => true);
      check(
        a?.name === "kill_vote" &&
          exact(p, ["actorId", "targetId", "abstain"]) &&
          equal(a.args, { target_id: p.targetId, abstain: p.abstain }),
      );
      return;
    }
    if (e.type === "sheriff_nomination_summary" || e.type === "sheriff_candidates_finalized") {
      const candidates = rows(factDay, ["sheriff_nomination"])
        .filter((x) => {
          const a = call(x);
          return a?.name === "run_for_sheriff" && a.args.run === true;
        })
        .map((x) => x.actorId);
      const withdrew = rows(factDay, ["sheriff_withdraw"])
        .filter((x) => {
          const a = call(x);
          return a?.name === "run_for_sheriff" && a.args.run === false;
        })
        .map((x) => x.actorId);
      check(
        settled(
          rows(
            factDay,
            e.type === "sheriff_nomination_summary"
              ? ["sheriff_nomination"]
              : ["sheriff_nomination", "sheriff_withdraw"],
          ),
        ) <= d.openedAfterSettlement &&
          exact(p, ["candidates"]) &&
          equal(
            p.candidates,
            e.type === "sheriff_nomination_summary"
              ? candidates
              : candidates.filter((id) => !withdrew.includes(id)),
          ),
      );
      return;
    }
    if (e.type === "sheriff_withdraw_summary") {
      const decisions = rows(factDay, ["sheriff_withdraw"]);
      check(
        settled(decisions) <= d.openedAfterSettlement &&
          exact(p, ["withdrawn"]) &&
          equal(
            p.withdrawn,
            decisions
              .filter((x) => {
                const a = call(x);
                return a?.name === "run_for_sheriff" && !a.args.run;
              })
              .map((x) => x.actorId),
          ),
      );
      return;
    }
    if (e.type === "day_speech") {
      const sources = rows(
        factDay,
        ["day_speech", "sheriff_campaign_speech", "sheriff_pk_speech", "exile_pk_speech"],
        Number(p.actorId),
      ).filter((x) => {
        const a = call(x);
        return (
          a?.name === "speak" &&
          sanitizeSpeechText(a.args.text) === p.text &&
          x.settleOrder !== undefined &&
          x.settleOrder <= d.openedAfterSettlement
        );
      });
      let number = 0;
      const seen = d.request.context.visible_events.slice(0, e.seq).filter((x) => {
        if (x.type === "phase_changed") number = Number(x.payload.day);
        return number === factDay && x.type === e.type && equal(x.payload, p);
      }).length;
      check(exact(p, ["actorId", "text"]) && sources.length >= seen);
      return;
    }
    if (e.type === "sheriff_vote_summary" || e.type === "sheriff_pk_started") return; // 此选举事实已由上文的选举账本校验。
    if (e.type === "sheriff_direction_chosen") {
      const a = source(["sheriff_choose_direction"], Number(p.sheriffId), () => true);
      check(
        exact(p, ["sheriffId", "direction"]) &&
          p.direction ===
            (a?.name === "choose_direction" &&
            ["clockwise", "counter_clockwise"].includes(a.args.direction)
              ? a.args.direction
              : "clockwise"),
      );
      return;
    }
    if (e.type === "wolf_self_destruct") {
      const a = source([String(p.window)], Number(p.wolfId), (x) => {
        const a = call(x);
        return a?.name === "self_destruct" && a.args.confirm === true;
      });
      const selected = selectedMistBlast(
        rows(factDay, [String(p.window)]),
        d.openedAfterSettlement,
      );
      check(
        roster.get(Number(p.wolfId))?.role === Role.Wolf &&
          a?.name === "self_destruct" &&
          a.args.confirm === true &&
          selected?.actorId === p.wolfId &&
          exact(p, ["wolfId", "window"]),
      );
      return;
    }
    if (e.type === "night_resolved") {
      check(exact(p, ["deaths"]) && equal(p.deaths, unpublishedDamage(d, factDay)));
      return;
    }
    if (e.type === "last_words_granted" || e.type === "last_words_spoken") {
      const before = d.request.context.visible_events.slice(0, e.seq - 1);
      check(p.day === factDay && [Phase.Day, Phase.Voting].includes(p.phase as Phase));
      if (e.type === "last_words_granted")
        check(
          exact(p, ["playerId", "phase", "day"]) &&
            before.some(
              (x) =>
                (x.type === "night_resolved" &&
                  factDay === 1 &&
                  Array.isArray(x.payload.deaths) &&
                  x.payload.deaths.includes(p.playerId)) ||
                (x.type === "voted_out" && x.payload.target === p.playerId),
            ),
        );
      else {
        const a = source(["last_words"], Number(p.playerId), (x) => x.request.phase === p.phase);
        check(
          exact(p, ["playerId", "phase", "day", "text"]) &&
            a?.name === "speak" &&
            sanitizeSpeechText(a.args.text) === p.text &&
            before.some(
              (x) =>
                x.type === "last_words_granted" &&
                x.payload.playerId === p.playerId &&
                x.payload.day === p.day &&
                x.payload.phase === p.phase,
            ),
        );
      }
      return;
    }
    if (e.type === "vote_summary") {
      const stage = p.round === 2 ? "exile_pk_vote" : "voting",
        ds = rows(factDay, [stage]);
      check(ds.length > 0 && settled(ds) <= d.openedAfterSettlement);
      const visibleBefore = d.request.context.visible_events.slice(0, e.seq - 1);
      const live = new Set(
        nights.get(factDay)?.start ??
          record.checkpoints
            .at(-1)!
            .players.filter((x) => x.alive)
            .map((x) => x.id),
      );
      for (const x of visibleBefore) {
        if (x.type === "night_resolved")
          for (const id of x.payload.deaths as number[]) live.delete(id);
        if (x.type === "wolf_self_destruct") live.delete(Number(x.payload.wolfId));
      }
      const pk =
        p.round === 2
          ? visibleBefore.filter((x) => x.type === "exile_pk_started").at(-1)?.payload.candidates
          : undefined;
      const eligible = Array.isArray(pk)
        ? (pk as number[])
        : [...live].filter(
            (id) =>
              !visibleBefore.some((x) => x.type === "idiot_revealed" && x.payload.targetId === id),
          );
      const actors = [...new Set(ds.map((x) => x.actorId))];
      const voters = actors.map((actor) => {
        const attempts = ds.filter((x) => x.actorId === actor);
        check(attempts.length <= 4 && attempts.every((x, i) => x.turn === i + 1));
        const selected = attempts.find((x) => {
          const a = call(x);
          return (
            a?.name === "vote" &&
            typeof a.args.abstain === "boolean" &&
            (a.args.abstain ||
              (typeof a.args.target_id === "number" && eligible.includes(a.args.target_id)))
          );
        });
        const a = selected && call(selected);
        check(!selected || selected === attempts.at(-1));
        let sheriff: unknown;
        for (const event of visibleBefore) {
          if (event.type === "sheriff_direction_chosen") sheriff = event.payload.sheriffId;
          if (event.type === "sheriff_badge_transferred") sheriff = event.payload.toId;
          if (event.type === "sheriff_badge_destroyed") sheriff = null;
        }
        const target = a?.name === "vote" ? a.args.target_id : null,
          abstain = a?.name === "vote" ? a.args.abstain : true;
        return {
          actorId: actor,
          targetId: target,
          abstain,
          weight: abstain ? 0 : actor === sheriff ? 1.5 : 1,
        };
      });
      const tally = new Map<number, number>();
      for (const v of voters)
        if (!v.abstain && v.targetId !== null)
          tally.set(v.targetId, (tally.get(v.targetId) ?? 0) + v.weight);
      const max = Math.max(0, ...tally.values()),
        top = [...tally].filter(([, n]) => n === max).map(([id]) => id);
      check(
        exact(p, ["votes", "target", "round"]) &&
          equal(p.votes, voters) &&
          p.target === (top.length === 1 ? top[0] : null),
      );
      return;
    }
    if (e.type === "exile_pk_started" || e.type === "voted_out" || e.type === "idiot_revealed") {
      const summary = d.request.context.visible_events
        .slice(0, e.seq - 1)
        .filter((x) => x.type === "vote_summary")
        .at(-1)?.payload;
      check(summary);
      if (e.type === "exile_pk_started") {
        const tally = new Map<number, number>();
        for (const v of summary.votes as Array<{
          targetId: number | null;
          abstain: boolean;
          weight: number;
        }>)
          if (!v.abstain && v.targetId !== null)
            tally.set(v.targetId, (tally.get(v.targetId) ?? 0) + v.weight);
        const max = Math.max(0, ...tally.values()),
          top = [...tally]
            .filter(([, n]) => n === max && max > 0)
            .map(([id]) => id)
            .sort((a, b) => a - b);
        check(exact(p, ["candidates"]) && top.length > 1 && equal(p.candidates, top));
      } else
        check(
          exact(p, [e.type === "voted_out" ? "target" : "targetId"]) &&
            (p.target ?? p.targetId) === summary.target &&
            (e.type !== "idiot_revealed" || roster.get(Number(p.targetId))?.role === Role.Idiot),
        );
      return;
    }
    if (e.type === "sheriff_badge_transferred" || e.type === "sheriff_badge_destroyed") {
      const actor = Number(p.fromId ?? p.targetId),
        ds = rows(factDay, ["sheriff_badge_choice"], actor);
      const a = ds[0] && call(ds[0]),
        candidates = ds[0]?.request.context.badge_candidates;
      check(ds.length === 1 && settled(ds) <= d.openedAfterSettlement && Array.isArray(candidates));
      const successor =
        a?.name === "choose_badge_successor" &&
        a.args.target_id !== null &&
        candidates.includes(a.args.target_id)
          ? a.args.target_id
          : null;
      check(
        e.type === "sheriff_badge_transferred"
          ? p.toId === successor && successor !== null
          : successor === null,
      );
      return;
    }
    // 公开发表的事实须结合完整状态账本验证，不能信任请求自报的信息。
    check(false);
  }

  function validateElectionFeed(d: RecordedDecision): void {
    const ledger = createMistSheriffEvidence(record);
    const alive = new Set(record.metadata.players.map((p) => p.id));
    let number = 1,
      phase = Phase.Night;
    const accept = (e: RecordedGameEvent) =>
      ledger.accept(e, {
        day: number,
        phase,
        alive,
        idiot: record.metadata.players.find((p) => p.role === Role.Idiot)!.id,
        idiotRevealed: false,
      });
    for (const e of d.request.context.visible_events) {
      if (e.type === "phase_changed") {
        number = Number(e.payload.day);
        phase = e.payload.phase as Phase;
      }
      if (e.type === "wolf_self_destruct") alive.delete(Number(e.payload.wolfId));
      if (e.type === "night_resolved")
        for (const id of e.payload.deaths as number[]) alive.delete(id);
      if (e.type === "sheriff_nomination_summary" || e.type === "sheriff_withdraw_summary") {
        const stage =
          e.type === "sheriff_nomination_summary" ? "sheriff_nomination" : "sheriff_withdraw";
        check(settled(rows(number, [stage])) <= d.openedAfterSettlement);
        for (const x of rows(number, [stage])) {
          const a = call(x);
          if (
            a?.name === "run_for_sheriff" &&
            typeof a.args.run === "boolean" &&
            (stage === "sheriff_nomination" || a.args.run === false)
          )
            accept({
              type: "sheriff_candidate_declared",
              timestamp: 0,
              payload: { actorId: x.actorId, run: a.args.run },
            });
        }
      }
      if (e.type === "sheriff_vote_summary") {
        const stage = e.payload.round === 2 ? "sheriff_pk_vote" : "sheriff_vote";
        check(settled(rows(number, [stage])) <= d.openedAfterSettlement);
        for (const x of rows(number, [stage])) {
          const a = call(x);
          if (
            a?.name === "vote_for_sheriff" &&
            typeof a.args.abstain === "boolean" &&
            (a.args.target_id === null ||
              (Number.isSafeInteger(a.args.target_id) && a.args.target_id! > 0)) &&
            (a.args.abstain
              ? a.args.target_id === null
              : x.request.context.sheriff_candidates?.includes(a.args.target_id!))
          )
            accept({
              type: "sheriff_vote_cast",
              timestamp: 0,
              payload: { actorId: x.actorId, targetId: a.args.target_id, abstain: a.args.abstain },
            });
        }
      }
      accept({ type: e.type, timestamp: 0, payload: e.payload });
    }
  }
  function unpublishedDamage(d: RecordedDecision, number: number): number[] {
    const n = nights.get(number),
      start =
        n?.start ??
        record.checkpoints
          .at(-1)!
          .players.filter((p) => p.alive)
          .map((p) => p.id);
    const before = record.decisions.filter(
      (x) =>
        x.day === number && x.settleOrder !== undefined && x.settleOrder <= d.openedAfterSettlement,
    );
    const action = (stage: string) => {
      const x = before.find((x) => x.stage === stage);
      return x && call(x);
    };
    const ballots = before.filter((x) => x.stage === "wolf_vote"),
      tally = new Map<number, number>();
    check(ballots.length > 0);
    for (const x of ballots) {
      const a = call(x);
      check(a?.name === "kill_vote");
      if (!a.args.abstain && a.args.target_id !== null)
        tally.set(a.args.target_id, (tally.get(a.args.target_id) ?? 0) + 1);
    }
    const max = Math.max(0, ...tally.values());
    const mist = action("alchemist_mist"),
      circle = mist?.name === "cast_mist" ? mist.args.target_ids : null;
    const knife =
      max > 0
        ? Math.min(...[...tally].filter(([, v]) => v === max).map(([id]) => id))
        : (circle?.[
            Math.floor(
              mistDraw(record.metadata.random.seed, [
                ...record.metadata.random.path,
                "night",
                `day:${number}:mist-knife`,
              ]) * circle.length,
            )
          ] ?? null);
    const dream = action("dreamer"),
      m = dream?.name === "dream" ? dream.args.target_id : null;
    const previous = rows(number - 1, ["dreamer"])[0],
      prior = previous && call(previous);
    const consecutive = prior?.name === "dream" && prior.args.target_id === m;
    const extra = action("raven_knife"),
      raven = extra?.name === "raven_knife" ? extra.args.target_id : null;
    const snake = action("alchemist_snake"),
      heal = snake?.name === "use_snake" ? snake.args.target_id : null;
    const alchemist = record.metadata.players.find((p) => p.role === Role.Alchemist)!.id;
    const stock = record.checkpoints.at(-1)!.players.find((p) => p.id === alchemist)!.privateState
      .alchemist as { healRemaining: number };
    if (n?.delay ?? (start.includes(alchemist) && stock.healRemaining === 1))
      check(snake?.name === "use_snake");
    const alive = new Set(start);
    const blast = selectedMistBlast(
      record.decisions.filter((x) => x.day === number && x.request.actionWindow !== "on_pre_vote"),
      d.openedAfterSettlement,
    );
    if (blast) alive.delete(blast.actorId);
    const causes = new Map<number, string[]>();
    const add = (id: number, cause: string) => {
      if (alive.has(id)) causes.set(id, [...(causes.get(id) ?? []), cause]);
    };
    if (knife !== null && knife !== m) add(knife, "wolf_kill");
    if (m !== null && consecutive) add(m, "dream");
    const ordered = [...causes].sort(([a], [b]) => a - b);
    causes.clear();
    for (const [id, list] of ordered) causes.set(id, list);
    if (raven !== null) add(raven, "raven_claw_knife");
    if (heal !== null) {
      const remaining = (causes.get(heal) ?? []).filter((c) => c !== "wolf_kill");
      if (remaining.length) causes.set(heal, remaining);
      else causes.delete(heal);
    }
    const dreamer = record.metadata.players.find((p) => p.role === Role.Dreamer)!.id;
    if (m !== null && causes.has(dreamer)) add(m, "dream");
    return [...causes.keys()];
  }
}

/**
 * 负责独立审核雾鸦警长选举、退水和逐轮票型。输入为归档配置、决定、事实与 checkpoint；
 * 输出为原一致性结果或明确拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import { Phase } from "@ai-werewolf-arena/game-contract";
import type { RecordedGameEvent, ReproductionRecord } from "./reproduction";
import { check, equal } from "./mist_raven_requests";

/** 此有限板子的警长选举证据，不复用放逐票或狼刀票的计票过程。 */
export function createMistSheriffEvidence(record: ReproductionRecord) {
  let nominated = false,
    withdrawn = false,
    initial: number[] = [],
    candidates: number[] = [],
    round = 1,
    winner: number | null = null,
    leaders: number[] = [];
  const declarations: number[] = [],
    withdrawals: number[] = [],
    ballots: Array<{ actorId: number; targetId: number | null; abstain: boolean }> = [];
  const rows = (stage: string, actor?: number) =>
    record.decisions.filter(
      (d) => d.day === 1 && d.stage === stage && (actor === undefined || d.actorId === actor),
    );
  const response = (stage: string, actor: number) => {
    const list = rows(stage, actor);
    check(list.length === 1);
    const d = list[0]!;
    check(
      d.request.phase === Phase.Day && d.outcome.kind === "action" && d.settleOrder !== undefined,
    );
    return d.outcome.action;
  };
  const nomination = (stage: string, actor: number) => {
    const a = response(stage, actor);
    return a?.name === "run_for_sheriff" && typeof a.args.run === "boolean" ? a.args.run : null;
  };
  const ballot = (actor: number) => {
    const stage = round === 1 ? "sheriff_vote" : "sheriff_pk_vote",
      a = response(stage, actor),
      d = rows(stage, actor)[0]!;
    check(
      equal(d.request.allowedTools, ["vote_for_sheriff"]) &&
        equal(d.request.context.sheriff_candidates, candidates),
    );
    if (round === 2) check(d.request.context.round === 2 && d.request.context.max_rounds === 2);
    if (a?.name !== "vote_for_sheriff") return null;
    const { target_id: target, abstain } = a.args;
    return typeof abstain === "boolean" &&
      (target === null ||
        (typeof target === "number" && Number.isSafeInteger(target) && target > 0)) &&
      (abstain ? target === null : target !== null && candidates.includes(target))
      ? { actorId: actor, targetId: target, abstain }
      : null;
  };
  return {
    get winner() {
      return winner;
    },
    accept(
      event: RecordedGameEvent,
      context: {
        day: number;
        phase: Phase;
        alive: ReadonlySet<number>;
        idiot: number;
        idiotRevealed: boolean;
      },
    ) {
      const { day, phase, alive, idiot, idiotRevealed } = context,
        p = event.payload;
      const eligible = [...alive]
        .filter((id) => id !== idiot || !idiotRevealed)
        .sort((a, b) => a - b);
      const electionEvents = [
        "sheriff_candidate_declared",
        "sheriff_nomination_summary",
        "sheriff_withdraw_summary",
        "sheriff_candidates_finalized",
        "sheriff_vote_cast",
        "sheriff_vote_summary",
        "sheriff_pk_started",
      ];
      if (!electionEvents.includes(event.type)) return;
      check(day === 1 && phase === Phase.Day);
      if (event.type === "sheriff_candidate_declared") {
        check(typeof p.actorId === "number" && eligible.includes(p.actorId));
        const selected = nomination(
          nominated ? "sheriff_withdraw" : "sheriff_nomination",
          p.actorId,
        );
        check(selected !== null && p.run === selected);
        if (!nominated) {
          check(!declarations.includes(p.actorId));
          declarations.push(p.actorId);
        } else {
          check(
            !withdrawn &&
              initial.includes(p.actorId) &&
              p.run === false &&
              !withdrawals.includes(p.actorId),
          );
          withdrawals.push(p.actorId);
        }
      }
      if (event.type === "sheriff_nomination_summary") {
        check(
          !nominated &&
            equal(
              rows("sheriff_nomination")
                .map((d) => d.actorId)
                .sort((a, b) => a - b),
              eligible,
            ),
        );
        const expected = eligible.filter((id) => nomination("sheriff_nomination", id) === true);
        check(
          equal(p.candidates, expected) &&
            equal(
              declarations,
              eligible.filter((id) => nomination("sheriff_nomination", id) !== null),
            ),
        );
        initial = expected;
        candidates = [...expected];
        nominated = true;
      }
      if (event.type === "sheriff_withdraw_summary") {
        check(
          nominated &&
            !withdrawn &&
            equal(
              rows("sheriff_withdraw")
                .map((d) => d.actorId)
                .sort((a, b) => a - b),
              initial,
            ),
        );
        const expected = initial.filter((id) => nomination("sheriff_withdraw", id) === false);
        check(equal(p.withdrawn, expected) && equal(withdrawals, expected));
        candidates = initial.filter((id) => !expected.includes(id));
        withdrawn = true;
      }
      if (event.type === "sheriff_candidates_finalized")
        check(withdrawn && equal(p.candidates, candidates));
      if (event.type === "sheriff_vote_cast") {
        check(
          withdrawn &&
            typeof p.actorId === "number" &&
            eligible.includes(p.actorId) &&
            !(round === 1 ? initial : candidates).includes(p.actorId) &&
            ballots.every((v) => v.actorId !== p.actorId),
        );
        const expected = ballot(p.actorId);
        check(expected && equal(p, expected));
        ballots.push(expected);
      }
      if (event.type === "sheriff_vote_summary") {
        check(withdrawn && (p.round ?? 1) === round);
        const voters =
          candidates.length === 0 || (round === 1 && candidates.length === 1)
            ? []
            : eligible.filter((id) => !(round === 1 ? initial : candidates).includes(id));
        check(
          equal(
            rows(round === 1 ? "sheriff_vote" : "sheriff_pk_vote")
              .map((d) => d.actorId)
              .sort((a, b) => a - b),
            voters,
          ),
        );
        const expected = voters.map(ballot).filter((v): v is NonNullable<typeof v> => v !== null);
        check(equal(ballots, expected) && equal(p.votes, expected));
        const counts = new Map(candidates.map((id) => [id, 0]));
        for (const v of expected)
          if (!v.abstain && v.targetId !== null)
            counts.set(v.targetId, (counts.get(v.targetId) ?? 0) + 1);
        const max = Math.max(0, ...counts.values());
        leaders = max > 0 ? [...counts].filter(([, n]) => n === max).map(([id]) => id) : [];
        winner =
          round === 1 && candidates.length === 1
            ? candidates[0]!
            : leaders.length === 1
              ? leaders[0]!
              : null;
        check(p.winnerId === winner);
      }
      if (event.type === "sheriff_pk_started") {
        check(round === 1 && leaders.length > 1 && winner === null && equal(p.candidates, leaders));
        candidates = [...leaders];
        round = 2;
        ballots.length = 0;
      }
    },
  };
}

/**
 * 负责独立审核婚约关系、婚刀资格和发表前缀。输入为归档配置、决定、事实与 checkpoint；
 * 输出为原一致性结果或明确拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import { z } from "zod";
import {
  GHOST_BRIDE_POLICY,
  GHOST_BRIDE_GOAL,
  GHOST_BRIDE_EVENT_TYPES,
  readGhostBrideState,
  readGhostBrideEventFact,
  readWeddingPair,
  readWeddingGroup,
  readWeddingKnifeCapture,
  readWeddingSetup,
  readWeddingTool,
  type WeddingPair,
  type WeddingGroup,
  type WeddingKnifeCapture,
  type WeddingVote,
} from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import { isGhostBridePreset } from "../verification/board-support";
import { Role, Camp, Phase } from "@ai-werewolf-arena/game-contract";
import type { ReproductionRecord, RecordedCheckpoint, RecordedDecision } from "./reproduction";
const setupStages = [
  "ghost_bride_groom",
  "ghost_bride_chat",
  "ghost_bride_chat",
  "ghost_bride_witness",
  "ghost_bride_witness",
];
const weddingTools = [
  "choose_bridegroom",
  "speak_to_partner",
  "choose_wedding_witness",
  "wedding_kill_vote",
];
const isFact = (type: string) => (GHOST_BRIDE_EVENT_TYPES as readonly string[]).includes(type);
function equal(a: unknown, b: unknown): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}
function assert(value: unknown): asserts value {
  if (!value) throw new Error("reproduction_ghost_bride_state_invalid");
}
function audience(actual: readonly number[] | undefined, expected: readonly number[]) {
  assert(
    equal(
      actual,
      [...new Set(expected)].sort((a, b) => a - b),
    ),
  );
}
interface Prefix {
  pair: WeddingPair | null;
  group: WeddingGroup | null;
  votes: WeddingVote[];
  chats: Map<number, number>;
  captures: Map<number, WeddingKnifeCapture>;
  ballots: Map<number, Array<{ actorId: number; targetId: number | null; abstain: boolean }>>;
  resolved: Set<number>;
}
function blank(): Prefix {
  return {
    pair: null,
    group: null,
    votes: [],
    chats: new Map(),
    captures: new Map(),
    ballots: new Map(),
    resolved: new Set(),
  };
}
/** 语义审核只消费严格序列化事实，不导入正在执行的引擎。 */
export function validateGhostBrideRecord(record: ReproductionRecord): void {
  const board = record.metadata.normalizedBoard;
  const owns = board.roleSetups.some((r) => r.role === Role.GhostBride && r.count > 0);
  const artifacts =
    record.events.some((e) => e.type.startsWith("ghost_bride_")) ||
    record.checkpoints.some(
      (c) =>
        c.ghostBrideSetup || c.players.some((p) => Object.hasOwn(p.privateState, "ghostBride")),
    ) ||
    record.decisions.some(
      (d) =>
        d.stage.startsWith("ghost_bride_") ||
        d.request.context.proposedWitnessId !== undefined ||
        d.request.allowedTools.some((t) => weddingTools.includes(t)),
    );
  if (!owns) {
    assert(
      !artifacts &&
        !board.ghostBride &&
        !board.winConditions?.includes(GHOST_BRIDE_GOAL as never) &&
        board.winCondition !== (GHOST_BRIDE_GOAL as never),
    );
    return;
  }
  assert(isGhostBridePreset(board));
  assert(!record.metadata.initialDeal);
  const ids = record.metadata.players.map((p) => p.id),
    idSet = new Set(ids);
  assert(ids.length === 12 && idSet.size === 12);
  const original = new Map(record.metadata.players.map((p) => [p.id, p]));
  const bride = record.metadata.players.filter((p) => p.role === Role.GhostBride);
  assert(bride.length === 1);
  const brideId = bride[0]!.id;
  const actualCounts = new Map<Role, number>();
  for (const p of record.metadata.players)
    actualCounts.set(p.role, (actualCounts.get(p.role) ?? 0) + 1);
  assert(
    actualCounts.size === board.roleSetups.length &&
      board.roleSetups.every((r) => actualCounts.get(r.role) === r.count),
  );
  for (const p of record.metadata.players)
    assert(
      p.camp ===
        (p.role === Role.GhostBride
          ? Camp.ThirdParty
          : p.role === Role.Wolf
            ? Camp.Wolf
            : Camp.Good),
    );
  const allKnown = (values: readonly number[]) => values.every((id) => idSet.has(id));
  const before = (eventIndex: number): RecordedCheckpoint => {
    const c = record.checkpoints.filter((c) => c.eventCount <= eventIndex).at(-1);
    assert(c);
    return c;
  };
  const memberIds = (group: WeddingGroup) => [group.brideId, group.groomId, group.witnessId];
  const captured = (group: WeddingGroup, day: number, eventIndex: number): WeddingKnifeCapture => {
    const c = before(eventIndex),
      alive = new Set(c.players.filter((p) => p.alive).map((p) => p.id));
    const prior = record.checkpoints[c.cycle - 1];
    const cycleEvents = record.events.slice(prior?.eventCount ?? 0, c.eventCount);
    const lastPhase = cycleEvents.filter((e) => e.type === "phase_changed").at(-1);
    const interruptedHandoff =
      c.snapshot.phase === Phase.Night &&
      cycleEvents.some((e) => e.type === "wolf_self_destruct") &&
      lastPhase?.payload.phase === Phase.Night &&
      lastPhase.payload.day === day;
    assert(
      c.complete &&
        c.snapshot.day === day &&
        !c.snapshot.gameOver &&
        (c.cycle === 0
          ? c.snapshot.phase === Phase.Night
          : c.snapshot.phase === Phase.Voting || interruptedHandoff),
    );
    const singles = record.metadata.players
      .filter((p) => p.role === Role.Wolf && !memberIds(group).includes(p.id) && alive.has(p.id))
      .map((p) => p.id)
      .sort((a, b) => a - b);
    const pair = [group.brideId, group.groomId],
      pairLive = pair.every((id) => alive.has(id)),
      pairDead = pair.every((id) => !alive.has(id));
    const owner = singles.length
      ? "ordinary_pack"
      : pairLive
        ? "pair"
        : pairDead && alive.has(group.witnessId)
          ? "witness"
          : "none";
    return {
      policy: GHOST_BRIDE_POLICY,
      groupId: group.groupId,
      day,
      owner,
      actorIds:
        owner === "ordinary_pack"
          ? singles
          : owner === "pair"
            ? pair
            : owner === "witness"
              ? [group.witnessId]
              : [],
    };
  };
  const states: Prefix[] = [blank()];
  let phase = Phase.Night,
    day = 1;
  const deathEdges = new Set<string>();
  for (let index = 0; index < record.events.length; index++) {
    const event = record.events[index]!,
      prev = states.at(-1)!,
      s: Prefix = {
        pair: prev.pair,
        group: prev.group,
        votes: [...prev.votes],
        chats: new Map(prev.chats),
        captures: new Map(prev.captures),
        ballots: new Map([...prev.ballots].map(([d, v]) => [d, [...v]])),
        resolved: new Set(prev.resolved),
      };
    if (event.type === "phase_changed") {
      phase = event.payload.phase as Phase;
      day = event.payload.day as number;
    }
    if (event.type.startsWith("ghost_bride_")) {
      assert(isFact(event.type));
      const p = readGhostBrideEventFact(event.type, event.payload);
      assert(p);
      assert(phase !== Phase.GameOver && p.groupId === `ghost-bride:1:${brideId}` && p.day === day);
      if (event.type !== "ghost_bride_partner_death") assert(phase === Phase.Night);
      if (event.type === "ghost_bride_pair_chosen") {
        const pair = readWeddingPair(p);
        assert(
          pair && !s.pair && day === 1 && pair.brideId === brideId && allKnown([pair.groomId]),
        );
        audience(event.audience, [pair.brideId, pair.groomId]);
        s.pair = pair;
      } else if (event.type === "ghost_bride_group_chosen") {
        const group = readWeddingGroup(p);
        assert(
          group &&
            s.pair &&
            !s.group &&
            equal(
              {
                policy: group.policy,
                groupId: group.groupId,
                brideId: group.brideId,
                groomId: group.groomId,
                day: group.day,
              },
              s.pair,
            ) &&
            allKnown(memberIds(group)) &&
            s.votes.length === 2 &&
            s.votes.every((v) => v.targetId === group.witnessId),
        );
        audience(event.audience, memberIds(group));
        s.group = group;
      } else {
        assert(s.pair);
        const pairIds = [s.pair.brideId, s.pair.groomId];
        if (event.type === "ghost_bride_partner_chat") {
          const n = s.chats.get(day) ?? 0;
          assert(n < 2 && p.actorId === pairIds[n] && p.recipientId === pairIds[1 - n]);
          if (day === 1) assert(!s.group && s.votes.length === 0);
          else {
            assert(s.group && s.captures.has(day));
            const c = before(index);
            assert(pairIds.every((id) => c.players.find((p) => p.id === id)?.alive));
          }
          audience(event.audience, pairIds);
          s.chats.set(day, n + 1);
        } else if (event.type === "ghost_bride_witness_vote") {
          assert(
            !s.group &&
              day === 1 &&
              s.chats.get(1) === 2 &&
              s.votes.length < 2 &&
              p.actorId === pairIds[s.votes.length] &&
              p.voteIndex === s.votes.length + 1 &&
              typeof p.targetId === "number" &&
              allKnown([p.targetId]) &&
              !pairIds.includes(p.targetId),
          );
          audience(event.audience, []);
          s.votes.push({ actorId: p.actorId as number, targetId: p.targetId });
        } else {
          assert(s.group);
          if (event.type === "ghost_bride_knife_captured") {
            const cap = readWeddingKnifeCapture(p);
            assert(
              cap &&
                !s.captures.has(day) &&
                day === s.captures.size + 1 &&
                equal(cap, captured(s.group, day, index)),
            );
            audience(event.audience, []);
            s.captures.set(day, cap);
            s.ballots.set(day, []);
          } else if (event.type === "ghost_bride_knife_vote") {
            const cap = s.captures.get(day),
              votes = s.ballots.get(day);
            assert(cap && votes && !s.resolved.has(day));
            const base = before(index),
              needsChat =
                day > 1 && pairIds.every((id) => base.players.find((p) => p.id === id)?.alive);
            assert(!needsChat || s.chats.get(day) === 2);
            assert(
              p.owner === cap.owner &&
                p.actorId === cap.actorIds[votes.length] &&
                (p.targetId === null ||
                  (typeof p.targetId === "number" &&
                    allKnown([p.targetId]) &&
                    base.players.find((q) => q.id === p.targetId)?.alive)),
            );
            if (cap.owner === "pair")
              assert(p.targetId === null || !pairIds.includes(p.targetId as number));
            if (cap.owner === "witness") assert(p.targetId !== p.actorId);
            audience(event.audience, cap.owner === "ordinary_pack" ? [] : [p.actorId as number]);
            votes.push({
              actorId: p.actorId as number,
              targetId: p.targetId as number | null,
              abstain: p.abstain as boolean,
            });
          } else if (event.type === "ghost_bride_knife_resolved") {
            const { targetId, ...capFact } = p,
              cap = s.captures.get(day),
              votes = s.ballots.get(day);
            assert(
              cap &&
                votes &&
                equal(capFact, cap) &&
                !s.resolved.has(day) &&
                votes.length === cap.actorIds.length,
            );
            const tally = new Map<number, number>();
            for (const v of votes)
              if (v.targetId !== null) tally.set(v.targetId, (tally.get(v.targetId) ?? 0) + 1);
            const selected = [...tally].sort((a, b) => b[1] - a[1] || a[0] - b[0])[0]?.[0] ?? null;
            assert(targetId === selected);
            audience(event.audience, cap.owner === "ordinary_pack" ? [] : cap.actorIds);
            s.resolved.add(day);
          } else if (event.type === "ghost_bride_partner_death") {
            const edge = `${p.actorId}:${p.targetId}`;
            assert(
              p.phase === phase &&
                pairIds.includes(p.actorId as number) &&
                pairIds.includes(p.targetId as number) &&
                !deathEdges.has(edge),
            );
            audience(event.audience, []);
            deathEdges.add(edge);
          }
        }
      }
    }
    if (
      event.type === "wolf_kill_vote_cast" ||
      ["wolf_tactical_order", "wolf_discussion", "wolf_discussion_ended"].includes(event.type)
    ) {
      const cap = s.captures.get(day);
      assert(phase === Phase.Night && cap?.owner === "ordinary_pack");
      audience(event.audience, cap.actorIds);
      if (event.type === "wolf_kill_vote_cast") {
        const vote = s.ballots.get(day)?.at(-1);
        assert(
          vote &&
            event.payload.actorId === vote.actorId &&
            event.payload.targetId === vote.targetId &&
            event.payload.abstain === vote.abstain &&
            !event.payload.fallback,
        );
      }
    }
    states.push(s);
  }
  for (const c of record.checkpoints) {
    assert(
      c.eventCount <= record.events.length &&
        !c.thiefSetup &&
        !c.shapeshifterSetup &&
        !c.lonelyGirlSetup,
    );
    const setup = readWeddingSetup(c.ghostBrideSetup),
      s = states[c.eventCount]!;
    assert(
      setup &&
        setup.actorId === brideId &&
        c.players.length === 12 &&
        new Set(c.players.map((p) => p.id)).size === 12 &&
        allKnown(c.players.map((p) => p.id)),
    );
    assert(
      setup.groomId === (s.pair?.groomId ?? null) &&
        setup.witnessId === (s.group?.witnessId ?? null) &&
        equal(setup.witnessVotes, s.votes),
    );
    if (s.group) assert(setup.status === "complete");
    else if (setup.status === "complete") assert(false);
    else if (s.pair && !["failed", "cancelled"].includes(setup.status))
      assert(setup.status === "paired");
    else if (!s.pair && !["failed", "cancelled"].includes(setup.status))
      assert(["pending", "active"].includes(setup.status));
    if (c.cycle === 0)
      assert(setup.status === "pending" && c.complete && c.players.every((p) => p.alive));
    if (c.cycle > 0 && !c.complete && !s.group)
      assert(["failed", "cancelled"].includes(setup.status));
    if (c.cycle > 0 && c.complete)
      assert(
        setup.status === "complete" &&
          s.resolved.has(c.snapshot.gameOver ? c.snapshot.day : c.snapshot.day - 1),
      );
    for (const p of c.players) {
      const native = original.get(p.id)!;
      assert(nativeInventory(p.role, p.privateState, idSet, c.cycle === 0, c.snapshot.day));
      assert(p.role === native.role && p.camp === native.camp && !p.lovers);
      const members = s.group ? memberIds(s.group) : s.pair ? [s.pair.brideId, s.pair.groomId] : [];
      const faction = members.includes(p.id) ? Camp.ThirdParty : native.camp;
      assert(equal(p.victory.affiliations, [{ kind: "faction", faction }]));
      if (p.id === brideId) {
        const brideState = readGhostBrideState(p.privateState.ghostBride);
        assert(
          brideState &&
            Object.keys(p.privateState).length === 1 &&
            brideState.groomId === setup.groomId,
        );
        assert(brideState.remaining === (["pending", "active"].includes(setup.status) ? 1 : 0));
      } else assert(!Object.hasOwn(p.privateState, "ghostBride"));
    }
    if (c.snapshot.result?.outcome.kind === "victory") {
      const outcome = c.snapshot.result.outcome;
      assert(
        s.group &&
          outcome.primary.kind === "faction" &&
          outcome.additional.length === 0 &&
          c.snapshot.result.reason === "three_factions_eliminated",
      );
      const winningFaction = outcome.primary.faction;
      const aliveFactions = new Set(
        c.players
          .filter((p) => p.alive)
          .map((p) =>
            p.victory.affiliations[0]!.kind === "faction"
              ? (p.victory.affiliations[0] as { faction: string }).faction
              : "",
          ),
      );
      assert(aliveFactions.size === 1 && aliveFactions.has(outcome.primary.faction));
      const winners = c.players
        .filter((p) =>
          p.victory.affiliations.some((a) => a.kind === "faction" && a.faction === winningFaction),
        )
        .map((p) => p.id)
        .sort((a, b) => a - b);
      assert(
        equal(outcome.winningPlayerIds, winners) &&
          equal(outcome.primary.winningPlayerIds, winners),
      );
    }
    if (c.snapshot.result?.reason === "three_factions_all_dead")
      assert(c.snapshot.result.outcome.kind === "no_winner" && c.players.every((p) => !p.alive));
  }
  const weddingDecisions = record.decisions.filter((d) => d.stage.startsWith("ghost_bride_"));
  let groomId: number | null = null,
    witness: number | null = null,
    setupCount = 0;
  for (const d of record.decisions) {
    for (const event of d.request.context.visible_events)
      if (event.type.startsWith("ghost_bride_")) {
        const p = readGhostBrideEventFact(event.type, event.payload);
        assert(p);
        if (event.type === "ghost_bride_pair_chosen")
          assert([p.brideId, p.groomId].includes(d.actorId));
        else if (event.type === "ghost_bride_group_chosen")
          assert([p.brideId, p.groomId, p.witnessId].includes(d.actorId));
        else if (event.type === "ghost_bride_partner_chat")
          assert([p.actorId, p.recipientId].includes(d.actorId));
        else if (event.type === "ghost_bride_knife_vote")
          assert(p.owner !== "ordinary_pack" && p.actorId === d.actorId);
        else if (event.type === "ghost_bride_knife_resolved")
          assert(p.owner !== "ordinary_pack" && (p.actorIds as number[]).includes(d.actorId));
        else assert(false);
      }
    if (setupCount < 5) {
      assert(
        d.stage === setupStages[setupCount] &&
          d.day === 1 &&
          d.request.phase === Phase.Night &&
          d.actorId ===
            (setupCount === 0 || setupCount === 1 || setupCount === 3 ? brideId : groomId),
      );
      assert(d.turn === 1 && d.openedAfterSettlement === setupCount);
      strictRequest(d);
      if (d.outcome.kind !== "action") {
        assert(d === record.decisions.at(-1));
        break;
      }
      const call = readWeddingTool(d.outcome.action);
      assert(call);
      if (setupCount === 0) {
        assert(
          call.name === "choose_bridegroom" &&
            idSet.has(call.args.target_id) &&
            call.args.target_id !== brideId,
        );
        groomId = call.args.target_id;
      } else if (setupCount === 1 || setupCount === 2) assert(call.name === "speak_to_partner");
      else {
        assert(
          call.name === "choose_wedding_witness" &&
            idSet.has(call.args.target_id) &&
            ![brideId, groomId].includes(call.args.target_id),
        );
        if (setupCount === 3) {
          witness = call.args.target_id;
          assert(d.request.context.proposedWitnessId === undefined);
        } else assert(d.request.context.proposedWitnessId === witness);
      }
