    if (
      ability.uses !== 2 - native.heal - native.poison ||
      (native.healUsedThisNight && native.poisonUsedThisNight)
    )
      return false;
    if (
      initial &&
      (native.heal !== 1 ||
        native.poison !== 1 ||
        native.healUsedThisNight ||
        native.poisonUsedThisNight)
