      const completeDeaths = [
        ...new Set([
          ...source.deaths,
          ...publicNight.shots,
          ...(redMoon?.expiredNights.has(source.day)
            ? [redMoon.expiredNights.get(source.day)!]
            : []),
        ]),
      ].sort((a, b) => a - b);
