/** 按已接受的决定独立计算有限原生库存；CP 值不能回填或刷新此账本。 */
export function validateDemonNativeStocks(
  record: ReproductionRecord,
  redMoon: RedMoonRecordAudit | null = null,
  noble: NobleRecordAudit | null = null,
): void {
  for (const cp of record.checkpoints) validateCheckpoint(record, cp, redMoon, noble);
}
function validateCheckpoint(
  record: ReproductionRecord,
  cp: RecordedCheckpoint,
  redMoon: RedMoonRecordAudit | null,
  noble: NobleRecordAudit | null,
): void {
  const original = new Map(record.metadata.players.map((p) => [p.id, p]));
  for (const p of cp.players) {
    const initial = original.get(p.id);
    assert(initial);
    if (cp.cycle === 0) assert(cp.complete && p.alive);
    if (initial.role === Role.NightNoble || initial.role === Role.AwakenedIdiot) {
      assert(noble);
      const expected = noble.at(cp);
      assert(
        stable(p.privateState) ===
          stable(
            initial.role === Role.NightNoble
              ? { noble: expected.noble }
              : { secretBody: expected.body },
          ),
      );
      continue;
    }
    if (String(initial.role) === "red_moon_apostle") {
      assert(
        redMoon && stable(p.privateState) === stable({ redMoon: redMoon.stateAt(cp.eventCount) }),
      );
      continue;
    }
    if (initial.role === Role.Idiot) {
      if (redMoon?.idiotRevealedAt(cp.eventCount))
        assert(p.vote.canVote === false && p.vote.weight === 0);
      assert(
        redMoon &&
          stable(p.privateState) ===
            stable({ idiot: { revealed: redMoon.idiotRevealedAt(cp.eventCount) } }),
      );
      continue;
    }
    if (initial.role === Role.DemonHunter) {
      assert(
        Object.keys(p.privateState).length === 1 && Object.hasOwn(p.privateState, "demonHunter"),
      );
      const state = readDemonHunterState(p.privateState.demonHunter);
      assert(state);
      const expected = record.events
        .slice(0, cp.eventCount)
        .filter((e) => e.type === "demon_hunter_chosen")
        .map((e) => ({ day: e.payload.day, targetId: e.payload.targetId }));
      assert(
        stable(state.history) === stable(expected) &&
          state.history.every(
            (row) => row.targetId === null || (original.has(row.targetId) && row.targetId !== p.id),
          ),
      );
      continue;
    }
    if (initial.role === Role.Wolf || initial.role === Role.Villager) {
      assert(stable(p.privateState) === "{}");
      continue;
    }
    if (initial.role === Role.Hunter) {
      const events = record.events.slice(0, cp.eventCount);
      // 仅死亡不会消耗枪权：三次无效或缺失的选择仍保留库存。
      // 此有限板子只有一名原生猎人；只有合法弃枪、已提交枪击，
      // 或真实的中毒抑制事件才能证明枪权消耗。
      const passed = record.decisions.some(
        (d) =>
          d.actorId === p.id &&
          d.day <= cp.cycle &&
          d.stage === "hunter_shot" &&
          d.outcome.kind === "action" &&
          d.outcome.action?.name === "shoot" &&
          d.outcome.action.args.target_id === null,
      );
      const consumed =
        passed ||
        events.some(
          (e) =>
            (e.type === "hunter_shot" || e.type === "hunter_silent_due_to_poison") &&
            e.payload.hunterId === p.id,
        );
      assert(
        stable(p.privateState) ===
          stable({ hunter: { canShoot: !consumed, deathActionPolicy: "awa_knife_or_exile_v1" } }),
      );
      continue;
    }
    const kind =
      initial.role === Role.Seer ? "seer_check" : initial.role === Role.Guard ? "guard" : "potion";
    assert([Role.Seer, Role.Guard, Role.Witch].includes(initial.role));
    const state: Record<string, any> =
      kind === "seer_check"
        ? { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] }
        : kind === "guard"
          ? { lastTarget: null, repeatPolicy: "netease_consecutive_nights_v1" }
          : {
              heal: 1,
              poison: 1,
              selfHealRule: "disabled",
              canSelfHeal: false,
              healUsedThisNight: false,
              poisonUsedThisNight: false,
            };
    const expected = native(initial.role, kind, state),
      stage = kind === "seer_check" ? "seer" : kind === "guard" ? "guard" : "witch";
    for (const d of record.decisions.filter(
      (d) => d.actorId === p.id && d.stage === stage && d.day <= cp.cycle,
    )) {
      if (kind === "potion") {
        state.healUsedThisNight = false;
        state.poisonUsedThisNight = false;
      }
      if (d.outcome.kind !== "action") continue;
      const call = d.outcome.action;
      assert(call);
      const target = "target_id" in call.args ? call.args.target_id : undefined;
      if (kind === "seer_check") {
        assert(
          call.name === "check_identity" && typeof target === "number" && original.has(target),
        );
        const result = { kind: "camp", camp: original.get(target)!.camp },
          isWerewolf = result.camp === Camp.Wolf;
        state.lastTarget = target;
        state.lastIsWerewolf = isWerewolf;
        state.lastResult = result;
        state.history.push({ targetId: target, isWerewolf, result });
        expected.uses++;
      } else if (kind === "guard") {
        assert(
          call.name === "guard" &&
            (target === null
              ? call.args.abstain === true
              : typeof target === "number" && original.has(target) && call.args.abstain === false),
        );
        assert(
          target === null || expected.lastUsedDay !== d.day - 1 || state.lastTarget !== target,
        );
        state.lastTarget = target;
        if (target !== null) expected.uses++;
      } else {
        assert(call.name === "use_potion");
        const potion = call.args.potion_type;
        if (potion !== "none") {
          assert(state[potion] === 1);
          state[potion] = 0;
          state[potion === "heal" ? "healUsedThisNight" : "poisonUsedThisNight"] = true;
          expected.uses++;
        }
      }
      expected.lastUsedDay = d.day;
    }
    assert(stable(p.privateState) === stable({ abilities: { [expected.id]: expected } }));
  }
}

/**
 * 负责独立审核红月延迟、转换与胜利前缀。输入为归档配置、决定、事实与 checkpoint；
 * 输出为独立重建的审计结果或原拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import { isRedMoonPreset } from "../verification/board-support";
import {
  readRedMoonNextNightFact,
  readRedMoonExpiryFact,
} from "@ai-werewolf-arena/game-contract/facts/red-moon";
import { Camp, Role, Phase, DeathCause } from "@ai-werewolf-arena/game-contract";
import type { ReproductionRecord } from "./reproduction";
const roleId = "red_moon_apostle";
const factTypes = new Set([
  "red_moon_night_sealed",
  "red_moon_exile_delayed",
  "red_moon_delay_expired",
]);
interface State {
  policy: "awa_red_moon_demon_v1";
  lastWolfBlastPolicy: "ends_game" | "forbidden";
  blastDay: number | null;
  exileDay: number | null;
  expirySettled: boolean;
}
export interface RedMoonRecordAudit {
  sealedNights: ReadonlySet<number>;
  expiredNights: ReadonlyMap<number, number>;
  stateAt(eventCount: number): State;
  idiotRevealedAt(eventCount: number): boolean;
}
function assert(value: unknown): asserts value {
  if (!value) throw new Error("reproduction_red_moon_state_invalid");
}
function equal(a: unknown, b: unknown): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}
/** 重建有限板子的公开状态迁移，不直接信任 checkpoint 中的库存。 */
export function validateRedMoonRecord(record: ReproductionRecord): RedMoonRecordAudit | null {
  const board = record.metadata.normalizedBoard;
  const owns = board.roleSetups.some((r) => String(r.role) === roleId && r.count > 0);
  const artifacts =
    record.events.some((e) => factTypes.has(e.type)) ||
    record.operations.some((o) => o.op === "red_moon_expiry_settled") ||
    record.checkpoints.some((cp) =>
      cp.players.some((p) => Object.hasOwn(p.privateState, "redMoon")),
    );
  if (!owns) {
    assert(!artifacts && !board.redMoon);
    return null;
  }
  assert(isRedMoonPreset(board) && !record.metadata.faultPlan && !record.metadata.initialDeal);
  const players = record.metadata.players,
    original = new Map(players.map((p) => [p.id, p]));
  const red = players.filter((p) => String(p.role) === roleId),
    idiots = players.filter((p) => p.role === Role.Idiot);
  assert(red.length === 1 && idiots.length === 1 && original.size === 12);
  const actorId = red[0]!.id,
    idiotId = idiots[0]!.id;
  const state: State = {
    policy: "awa_red_moon_demon_v1",
    lastWolfBlastPolicy: board.redMoon!.lastWolfBlastPolicy,
    blastDay: null,
    exileDay: null,
    expirySettled: false,
  };
  const states: State[] = [{ ...state }],
    idiotStates = [false];
  const alive = new Set(players.map((p) => p.id)),
    sealedNights = new Set<number>(),
    expiredNights = new Map<number, number>();
  const frozen = record.operations.filter((o) => o.op === "demon_hunter_sources_frozen");
  const expiryOps = record.operations.filter((o) => o.op === "red_moon_expiry_settled");
  let day = 1,
    phase: string = Phase.Night,
    voteTarget: number | null = null,
    idiotRevealed = false;
  let pendingSeal: number | null = null;
  const wolfCount = () => [...alive].filter((id) => original.get(id)?.camp === Camp.Wolf).length;
  const ordinaryAlive = (night: number) => {
    const op = frozen.find((o) => o.output?.day === night);
    assert(op && Array.isArray(op.output?.deaths));
    const ids = op.output.deaths as unknown[];
    assert(ids.every((id) => typeof id === "number" && original.has(id)));
    const remaining = new Set(alive);
    for (const id of ids) remaining.delete(id as number);
    return remaining;
  };
  const goodSidesRemain = (remaining: Set<number>) =>
    [...remaining].some((id) => original.get(id)?.role === Role.Villager) &&
    [...remaining].some(
      (id) => original.get(id)?.camp === Camp.Good && original.get(id)?.role !== Role.Villager,
    );
  for (let index = 0; index < record.events.length; index++) {
    const e = record.events[index]!;
    if (pendingSeal !== null) assert(e.type === "red_moon_night_sealed");
    if (e.type === "phase_changed") {
      assert(
        typeof e.payload.day === "number" &&
          Number.isSafeInteger(e.payload.day) &&
          e.payload.day > 0,
      );
      day = e.payload.day;
      phase = String(e.payload.phase);
      voteTarget = null;
    }
    if (e.type === "vote_summary") {
      assert(
        phase === Phase.Voting &&
          (e.payload.target === null || typeof e.payload.target === "number"),
      );
      voteTarget = e.payload.target as number | null;
    }
    if (e.type === "wolf_self_destruct") {
      const id = e.payload.wolfId;
      assert(typeof id === "number" && alive.has(id) && original.get(id)?.camp === Camp.Wolf);
      if (id === actorId) {
        assert(
          (phase === Phase.Day || phase === Phase.Voting) &&
            state.blastDay === null &&
            state.exileDay === null,
        );
        assert(wolfCount() > 1 || state.lastWolfBlastPolicy === "ends_game");
        pendingSeal = wolfCount() > 1 ? day : null;
        state.blastDay = day;
      }
      alive.delete(id);
    }
    if (e.type === "red_moon_night_sealed") {
      const fact = readRedMoonNextNightFact(e.type, e.payload);
      assert(
        fact &&
          fact.actorId === actorId &&
          fact.day === day &&
          pendingSeal === day &&
          record.events[index - 1]?.type === "wolf_self_destruct" &&
          record.events[index - 1]?.payload.wolfId === actorId &&
          !sealedNights.has(fact.night),
      );
      sealedNights.add(fact.night);
      pendingSeal = null;
    }
    if (e.type === "red_moon_exile_delayed") {
      const fact = readRedMoonNextNightFact(e.type, e.payload);
      assert(
        fact &&
          fact.actorId === actorId &&
          fact.day === day &&
          phase === Phase.Voting &&
          voteTarget === actorId &&
          alive.has(actorId) &&
          wolfCount() === 1 &&
          state.blastDay === null &&
          state.exileDay === null,
      );
      state.exileDay = day;
    }
    if (e.type === "idiot_revealed") {
      assert(
        e.payload.targetId === idiotId &&
          phase === Phase.Voting &&
          voteTarget === idiotId &&
          alive.has(idiotId) &&
          !idiotRevealed,
      );
      idiotRevealed = true;
    }
    if (e.type === "voted_out") {
      const id = e.payload.target;
      assert(
        typeof id === "number" && alive.has(id) && phase === Phase.Voting && voteTarget === id,
      );
      assert(id !== idiotId && !(id === actorId && wolfCount() === 1));
      alive.delete(id);
    }
    if (e.type === "red_moon_delay_expired") {
      const fact = readRedMoonExpiryFact(e.type, e.payload);
      assert(
        fact &&
          fact.actorId === actorId &&
          fact.day === day &&
          phase === Phase.Night &&
          state.exileDay === day - 1 &&
          !state.expirySettled &&
          alive.has(actorId) &&
          !expiredNights.has(day),
      );
      if (record.finalized) {
        const remaining = ordinaryAlive(day);
        assert(remaining.has(actorId) && goodSidesRemain(remaining));
        const ops = expiryOps.filter((o) => o.output?.day === day),
          source = frozen.find((o) => o.output?.day === day)!;
        assert(ops.length === 1);
        const op = ops[0]!;
        assert(
          op.scope === "resolution" &&
            op.phase === Phase.Night &&
            op.status === "ok" &&
            op.input === undefined &&
            equal(op.output, { actorId, day, cause: DeathCause.RedMoonExpiry }) &&
            record.operations.indexOf(source) < record.operations.indexOf(op),
        );
      }
      state.expirySettled = true;
      expiredNights.set(day, actorId);
    }
    if (e.type === "night_resolved") {
      assert(phase === Phase.Night && Array.isArray(e.payload.deaths));
      const deaths = e.payload.deaths as number[];
      assert(
        deaths.length === new Set(deaths).size &&
          deaths.every((id) => original.has(id) && alive.has(id)),
      );
      if (record.finalized) {
        const remaining = ordinaryAlive(day);
        const shouldExpire =
          state.exileDay === day - 1 && remaining.has(actorId) && goodSidesRemain(remaining);
        assert(expiredNights.has(day) === shouldExpire);
        if (shouldExpire) assert(deaths.includes(actorId));
      }
      for (const id of deaths) alive.delete(id);
    }
    if (factTypes.has(e.type)) assert(e.audience === undefined);
    states.push({ ...state });
    idiotStates.push(idiotRevealed);
  }
  if (record.finalized) {
    assert(expiryOps.length === expiredNights.size);
    if (record.checkpoints.at(-1)?.complete) assert(pendingSeal === null);
  }
  for (const d of record.decisions) {
    if (sealedNights.has(d.day)) assert(!["seer", "witch", "demon_hunter"].includes(d.stage));
    for (const e of d.request.context.visible_events) {
      if (!factTypes.has(e.type)) continue;
      assert(
        record.events.some((source) => source.type === e.type && equal(source.payload, e.payload)),
      );
    }
  }
  return {
    sealedNights,
    expiredNights,
    stateAt(count) {
      assert(Number.isSafeInteger(count) && count >= 0 && count < states.length);
      return { ...states[count]! };
    },
    idiotRevealedAt(count) {
      assert(Number.isSafeInteger(count) && count >= 0 && count < idiotStates.length);
      return idiotStates[count]!;
    },
  };
}

/**
 * 负责独立审核日蚀行动、继承与发表因果前缀。输入为归档配置、决定、事实与 checkpoint；
 * 输出为原一致性结果或明确拒绝，原纯数据推导、迭代与第一失败顺序保持。
 * 稳定枚举来自中立契约，不通过 barrel 加载 World／生产伤害；不读取或写入真实库存。
 * 结构读器仅确认数据；既有算法只消费归档，不授予游戏权限，也不替换原拒绝政策。
 */
import { isRadiantEclipsePreset } from "../verification/board-support";
import {
  RADIANT_ECLIPSE_EVENT_TYPES,
  readRadiantEclipseFact,
  radiantEclipseAudience,
} from "@ai-werewolf-arena/game-contract/facts/radiant-eclipse";
import { Camp, Phase, Role } from "@ai-werewolf-arena/game-contract";
import type { RecordedCheckpoint, RecordedDecision, ReproductionRecord } from "./reproduction";
import { createMistSheriffEvidence } from "./mist_raven_sheriff_record";
import { sanitizeSpeechText } from "../utils/speech_text";

/** 独立审核有限板子的证据，不导入生产能力、夜间 frame、目标或伤害实现。 */
export function radiantCheck(value: unknown): asserts value {
  if (!value) throw Error("reproduction_radiant_eclipse_invalid");
}
export function radiantEqual(a: unknown, b: unknown): boolean {
  const stable = (v: unknown): unknown =>
    Array.isArray(v)
      ? v.map(stable)
      : v && typeof v === "object"
        ? Object.fromEntries(
            Object.entries(v)
              .filter(([, x]) => x !== undefined)
              .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
              .map(([k, x]) => [k, stable(x)]),
          )
        : v;
  return JSON.stringify(stable(a)) === JSON.stringify(stable(b));
}
const check: (value: unknown) => asserts value = radiantCheck;
const equal = radiantEqual,
  policy = "awa_radiant_eclipse_v1";
export type RadiantAbility = {
  id: string;
  kind: "shelter" | "seer_check" | "potion" | "dream";
  state: Record<string, any>;
  source: Record<string, unknown>;
  sourceDisclosed: true;
  startsOnDay: number;
  expiresAfterDay?: number;
  maxUses: null;
  uses: number;
  lastUsedDay: number | null;
  disabled: boolean;
};
export interface RadiantNightEvidence {
  day: number;
  start: number[];
  before: Map<number, RadiantAbility | undefined>;
  previousSwallow: { day: number; targetId: number | null } | undefined;
  copy: RadiantAbility | undefined;
  target: number | null;
  swallowed: boolean;
  suppressed: boolean;
  restored: boolean;
  closed: "committed" | "aborted" | null;
  shelters: Map<number, number | null>;
  dreams: Array<{
    actorId: number;
    targetId: number;
    day: number;
    consecutive: boolean;
    abilityId?: string;
  }>;
  potions: Set<number>;
  checks: Set<number>;
  wolfOrder: number[] | null;
  wolfVotes: Map<number, number | null>;
  knife: number | null;
  heal: number | null;
  poisons: Set<number>;
  blast: boolean;
  settled: boolean;
  damage: { deaths: number[]; death_sources: Record<number, string[]> } | null;
  reasons: Array<Record<string, unknown>>;
  reasonsSeen: number;
}
const rolesToKind: Partial<Record<Role, RadiantAbility["kind"]>> = {
  [Role.RadiantCount]: "shelter",
  [Role.Seer]: "seer_check",
  [Role.Witch]: "potion",
  [Role.Dreamer]: "dream",
};
function native(role: Role): RadiantAbility | undefined {
  const kind = rolesToKind[role];
  if (!kind) return;
  const state =
    kind === "shelter"
      ? { policy, lastTarget: null, lastDay: null }
      : kind === "seer_check"
        ? { lastTarget: null, lastIsWerewolf: null, lastResult: null, history: [] }
        : kind === "potion"
          ? {
              heal: 1,
              poison: 1,
              selfHealRule: "disabled",
              canSelfHeal: false,
              healUsedThisNight: false,
              poisonUsedThisNight: false,
            }
          : {
              lastTarget: null,
              lastDay: null,
              history: [],
              protectionPolicy: "netease_2026_night_immunity_v1",
            };
  return {
    id: `native:${kind}`,
    kind,
    state,
    source: { kind: "native", role },
    sourceDisclosed: true,
    startsOnDay: kind === "shelter" ? 2 : 1,
    maxUses: null,
    uses: 0,
    lastUsedDay: null,
    disabled: false,
  };
}
export function radiantBorrow(
  source: RadiantAbility,
  actorId: number,
  day: number,
): RadiantAbility {
  const s = source.state,
    kind = source.kind;
  const state =
    kind === "shelter"
      ? { policy, lastTarget: s.lastTarget, lastDay: s.lastDay }
      : kind === "seer_check"
        ? {
            targetPolicy: "awa_alive_v1",
            actionPolicy: "awa_required_when_legal_v1",
            lastTarget: null,
            lastIsWerewolf: null,
            lastResult: null,
            history: [],
          }
        : kind === "potion"
          ? {
              heal: s.heal,
              poison: s.poison,
              selfHealRule: "disabled",
              knifeVisibility: "awa_with_heal_v1",
              potionPolicy: "awa_one_native_v1",
              canSelfHeal: false,
              healUsedThisNight: false,
              poisonUsedThisNight: false,
            }
          : {
              lastTarget: s.lastTarget,
              lastDay: s.lastDay,
              protectionPolicy: "netease_2026_night_immunity_v1",
              history: [],
            };
  return {
    id: `copy:eclipse:night:${day}`,
    kind,
    state,
    source: { kind: "copy", actorId, abilityId: source.id },
    sourceDisclosed: true,
    startsOnDay: day,
    expiresAfterDay: day,
    maxUses: null,
    uses: 0,
    lastUsedDay: null,
    disabled: false,
  };
}
export function validateRadiantEclipseRecord(record: ReproductionRecord): void {
  const board = record.metadata.normalizedBoard,
    owns = board.roleSetups.some(
      (p) => (p.role === Role.RadiantCount || p.role === Role.EclipseMaid) && p.count > 0,
    );
  const artifacts =
    record.events.some((e) =>
      (RADIANT_ECLIPSE_EVENT_TYPES as readonly string[]).includes(e.type),
    ) ||
    record.decisions.some(
      (d) =>
        ["eclipse_swallow", "radiant_shelter"].includes(d.stage) ||
        d.request.allowedTools.some((t) => ["cast_shelter", "swallow_skill"].includes(t)) ||
        Object.hasOwn(d.request.context, "shelter_candidates") ||
        Object.hasOwn(d.request.context, "swallow_candidates") ||
        d.request.context.ability_id?.startsWith("copy:eclipse:"),
    ) ||
    record.checkpoints.some((c) =>
      c.players.some(
        (p) =>
          Object.hasOwn(p.privateState, "eclipse") ||
          Object.values((p.privateState.abilities ?? {}) as Record<string, any>).some(
            (a) => a.kind === "shelter" || a.id?.startsWith("copy:eclipse:"),
          ),
      ),
    );
  if (!owns) {
    check(!board.radiantEclipse && !artifacts);
    return;
  }
  check(
    isRadiantEclipsePreset(board) && !record.metadata.faultPlan && !record.metadata.initialDeal,
  );
  if (record.finalized)
    check(
      record.decisions.every((d) => d.outcome.kind !== "pending") &&
        record.checkpoints.at(-1)!.eventCount === record.events.length,
    );
  const roster = new Map(record.metadata.players.map((p) => [p.id, p]));
  check(
    equal(
      [...roster.keys()].sort((a, b) => a - b),
      Array.from({ length: 12 }, (_, i) => i + 1),
    ),
  );
  for (const [role, count] of [
    [Role.EclipseMaid, 1],
    [Role.RadiantCount, 1],
    [Role.Seer, 1],
    [Role.Witch, 1],
    [Role.Dreamer, 1],
    [Role.Villager, 4],
    [Role.Wolf, 3],
  ] as const)
    check([...roster.values()].filter((p) => p.role === role).length === count);
  for (const p of roster.values())
    check(p.camp === ([Role.Wolf, Role.EclipseMaid].includes(p.role) ? Camp.Wolf : Camp.Good));
  const actor = (role: Role) => [...roster.values()].find((p) => p.role === role)!.id;
  const maid = actor(Role.EclipseMaid),
    count = actor(Role.RadiantCount),
    seer = actor(Role.Seer),
    witch = actor(Role.Witch),
    dreamer = actor(Role.Dreamer);
  const alive = new Set(roster.keys()),
    abilities = new Map<number, Map<string, RadiantAbility>>(
      [...roster].map(([id, p]) => {
