              record.decisions.filter(
                (d) =>
                  d.day === 1 &&
                  [
                    "sheriff_nomination",
                    "sheriff_withdraw",
                    "sheriff_campaign_speech",
                    "sheriff_vote",
                    "sheriff_pk_vote",
                    "sheriff_pk_speech",
                    "on_pre_election",
                  ].includes(d.stage),
              ),
            )
          : 0,
        e.payload.phase === Phase.Voting
          ? max(
              record.decisions.filter(
                (d) => d.day === day && ["voting", "exile_pk_vote"].includes(d.stage),
              ),
            )
          : 0,
      );
    if (e.type === "wolf_self_destruct")
      return max(record.decisions.filter((d) => d.day === day && d.stage === e.payload.window));
    return Number.MAX_SAFE_INTEGER;
  };
  const published = new Map(
    [...roster.keys()].map((id) => [
      id,
      [] as Array<{ type: string; payload: Record<string, unknown>; release: number; day: number }>,
    ]),
  );
  let eventDay = 1;
  for (const e of record.events) {
    if (e.type === "phase_changed") eventDay = Number(e.payload.day);
    const boundary = release(e, eventDay);
    for (const id of roster.keys()) {
      const p = project(e, id);
      if (p)
        published.get(id)!.push({ type: e.type, payload: p, release: boundary, day: eventDay });
    }
  }
  const used = new Set<string>();
  for (const d of record.decisions) {
    const key = `${d.actorId}/${d.day}/${d.stage}/${d.turn}`;
    check(!used.has(key));
    used.add(key);
    if (d.outcome.kind === "action" && d.outcome.action?.name === "speak")
      check(
        Object.keys(d.outcome.action.args).length === 1 &&
          Object.hasOwn(d.outcome.action.args, "text"),
      );
    check(
      roster.has(d.actorId) &&
        d.request.actorId === d.actorId &&
        d.request.context.day === d.day &&
        d.request.context.stage === d.stage &&
        stageTools[d.stage] &&
        equal(d.request.allowedTools, stageTools[d.stage]),
    );
    const ctx = d.request.context,
      isNight = [
        "eclipse_swallow",
        "radiant_shelter",
        "dreamer",
        "witch",
        "seer",
        "wolf_discussion",
        "wolf_vote",
      ].includes(d.stage);
    if (isNight) {
      const allowed = [
        "day",
        "stage",
        "visible_events",
        "turn_constraints",
        "allow_fallback",
        "action_failure_policy",
        ...(d.stage === "eclipse_swallow" ? ["swallow_candidates"] : []),
        ...(d.stage === "radiant_shelter" ? ["ability_id", "shelter_candidates"] : []),
        ...(["witch", "seer", "dreamer"].includes(d.stage) ? ["ability_id"] : []),
        ...(d.stage === "witch" ? ["wolf_target"] : []),
        ...(d.stage === "wolf_discussion" ? ["round", "max_rounds"] : []),
      ];
      check(Object.keys(ctx).every((key) => allowed.includes(key)));
      const n = info(d.day),
        s = swallow(d.day),
        kind = stageKinds[d.stage];
      check(
        d.request.phase === Phase.Night &&
          n.start.includes(d.actorId) &&
          ctx.allow_fallback === false &&
          ctx.action_failure_policy === "error",
      );
      check(
        ctx.turn_constraints.min_valid_actions === 1 &&
          ctx.turn_constraints.max_valid_actions === 1 &&
          equal(ctx.turn_constraints.required_any_tools, d.request.allowedTools),
      );
      if (d.stage === "eclipse_swallow") {
        check(d.day >= 2 && d.actorId === maid && d.turn === 1 && ctx.ability_id === undefined);
        const candidates = n.start.filter(
          (id) =>
            roster.get(id)!.camp === Camp.Good &&
            !(n.previousSwallow?.day === d.day - 1 && n.previousSwallow.targetId === id),
        );
        check(equal(ctx.swallow_candidates, candidates) && ctx.shelter_candidates === undefined);
      } else if (kind) {
        const a = d.actorId === maid ? s.borrowed : n.before.get(d.actorId);
        check(
          a &&
            a.kind === kind &&
            d.day >= a.startsOnDay &&
            ctx.ability_id === a.id &&
            d.turn === 1 &&
            (d.actorId === maid
              ? s.legal && s.d!.settleOrder! <= d.openedAfterSettlement
              : !s.legal || s.target !== d.actorId),
        );
        if (kind === "shelter") {
          const ids = n.start.filter(
            (id) =>
              id !== d.actorId && !(a.state.lastDay === d.day - 1 && a.state.lastTarget === id),
          );
          check(equal(ctx.shelter_candidates, ids));
        }
        if (kind === "potion") {
          check(d.actorId !== maid || a.state.heal > 0 || a.state.poison > 0);
          if (a.state.heal > 0) {
            const votes = record.decisions.filter(
                (x) =>
                  x.day === d.day &&
                  x.stage === "wolf_vote" &&
                  x.settleOrder !== undefined &&
                  x.settleOrder <= d.openedAfterSettlement,
              ),
              tally = new Map<number, number>();
            for (const v of votes) {
              const a = v.outcome.kind === "action" ? v.outcome.action : null;
              if (a?.name === "kill_vote" && !a.args.abstain && a.args.target_id !== null)
                tally.set(a.args.target_id, (tally.get(a.args.target_id) ?? 0) + 1);
            }
            const knife = [...tally].sort(([a, x], [b, y]) => y - x || a - b)[0]?.[0] ?? null;
            check(ctx.wolf_target === knife);
          } else check(!Object.hasOwn(ctx, "wolf_target"));
        }
      } else {
        const wolves = n.start.filter((id) => roster.get(id)!.role === Role.Wolf),
          holders = wolves.length ? wolves : n.start.includes(maid) ? [maid] : [];
        check(
          ctx.ability_id === undefined &&
            (d.stage === "wolf_discussion" ? wolves : holders).includes(d.actorId),
        );
        if (d.stage === "wolf_discussion") {
          check(d.turn <= 3 && ctx.round === d.turn && ctx.max_rounds === 3);
          for (const prior of record.decisions.filter(
            (x) =>
              x.day === d.day && x.stage === d.stage && x.actorId === d.actorId && x.turn < d.turn,
          )) {
            const a = prior.outcome.kind === "action" ? prior.outcome.action : null;
            check(
              a?.name === "speak_to_wolves" &&
                a.args.end_chat === false &&
                prior.settleOrder! <= d.openedAfterSettlement,
            );
          }
        } else check(d.turn === 1);
      }
      for (const name of ["shelter_candidates", "swallow_candidates"] as const)
        if (Object.hasOwn(ctx, name))
          check(
            d.stage === (name === "shelter_candidates" ? "radiant_shelter" : "eclipse_swallow"),
          );
    } else {
      check(
        ctx.ability_id === undefined &&
          !Object.hasOwn(ctx, "shelter_candidates") &&
          !Object.hasOwn(ctx, "swallow_candidates"),
      );
      if (d.stage === "on_pre_election" || d.stage === "on_pre_vote")
        check(
          roster.get(d.actorId)!.role === Role.Wolf &&
            d.request.phase === (d.stage === "on_pre_vote" ? Phase.Voting : Phase.Day),
        );
    }
    const visible = ctx.visible_events;
    check(visible.every((v, i) => v.seq === i + 1));
    const sources = published.get(d.actorId)!.filter((v) => v.release <= d.openedAfterSettlement);
    let expected = sources.map(({ release: _release, day: _day, ...v }) => v);
    if (!record.finalized) {
      const allPublished = published.get(d.actorId)!.filter((v) => v.day === d.day);
      const extra = (prefixes.get(d.day) ?? [])
        .filter((f) => f.release <= d.openedAfterSettlement)
        .flatMap((f) => {
          const p = project({ ...f.event, timestamp: 0 }, d.actorId);
          return p && !allPublished.some((v) => v.type === f.event.type && equal(v.payload, p))
            ? [{ type: f.event.type, payload: p }]
            : [];
        });
      expected = [...expected, ...extra];
    }
    check(
      equal(
        visible.map(({ seq: _seq, ...v }) => v),
        expected,
      ),
    );
    const latestPhase = [...visible].reverse().find((v) => v.type === "phase_changed");
    check(
      !!latestPhase &&
        latestPhase.payload.phase === d.request.phase &&
        latestPhase.payload.day === d.day,
    );
  }
}

import type { RecordedDecision, RecordedGameEvent, ReproductionRecord } from "./reproduction";
import { Role, Camp } from "../core/domain/identity";
import {
  radiantCheck as check,
  radiantEqual as equal,
  radiantBorrow,
  type RadiantAbility,
  type RadiantNightEvidence,
} from "./radiant_eclipse_record";
import { sanitizeSpeechText } from "../utils/speech_text";
export interface RadiantReleasedFact {
  event: Omit<RecordedGameEvent, "timestamp">;
  release: number;
}
/** A serial, independently calculated request prefix. Invalid/unfinished predecessors cannot open successors. */
export function radiantNightRequestPrefix(
  record: ReproductionRecord,
  day: number,
  n: Pick<RadiantNightEvidence, "start" | "before" | "previousSwallow">,
  roster: ReadonlyMap<number, ReproductionRecord["metadata"]["players"][number]>,
): RadiantReleasedFact[] {
  const ds = record.decisions.filter((d) => d.day === day && d.request.phase === "night"),
    facts: RadiantReleasedFact[] = [];
  if (!ds.length) return facts;
  const actor = (role: Role) => [...roster.values()].find((p) => p.role === role)!.id,
    maid = actor(Role.EclipseMaid),
    count = actor(Role.RadiantCount);
  let cursor = 0,
    stopped = false,
    target: number | null = null,
    borrowed: RadiantAbility | undefined,
    lastRelease = Math.max(
      0,
      ...record.decisions.filter((d) => d.day < day).map((d) => d.settleOrder ?? 0),
    );
  const emit = (
    type: string,
    payload: Record<string, unknown>,
    release: number,
    audience?: readonly number[],
  ) =>
    facts.push({
      event: { type, payload, ...(audience ? { audience: [...audience] } : {}) },
      release,
    });
  emit("phase_changed", { phase: "night", day }, lastRelease);
  const step = (
    stage: string,
    id: number,
    tool: string,
    keys: string[],
    legal: (a: Record<string, any>) => boolean,
  ): { d: RecordedDecision; args: Record<string, any> } | null => {
    if (stopped) return null;
    const d = ds[cursor];
    if (!d) {
      stopped = true;
      return null;
    }
    check(d.stage === stage && d.actorId === id && d.openedAfterSettlement === lastRelease);
    cursor++;
    const a = d.outcome.kind === "action" ? d.outcome.action : null;
    const required = a?.name === tool && keys.every((k) => Object.hasOwn(a.args, k));
    if (required) check(Object.keys(a!.args).length === keys.length);
    if (
      d.outcome.kind === "pending" ||
      d.outcome.kind === "error" ||
      !a ||
      a.name !== tool ||
      !required ||
      !legal(a.args)
    ) {
      check(cursor === ds.length);
      stopped = true;
      return null;
    }
    check(d.settleOrder !== undefined);
    lastRelease = d.settleOrder;
    return { d, args: a.args };
  };
  if (day >= 2 && n.start.includes(maid)) {
    const result = step(
      "eclipse_swallow",
      maid,
      "swallow_skill",
      ["target_id"],
      (a) =>
        a.target_id === null ||
        (Number.isSafeInteger(a.target_id) &&
          n.start.includes(a.target_id) &&
          roster.get(a.target_id)!.camp === Camp.Good &&
          !(n.previousSwallow?.day === day - 1 && n.previousSwallow.targetId === a.target_id)),
    );
    if (!result) return facts;
    target = result.args.target_id;
    const source = target === null ? undefined : n.before.get(target);
    if (source) {
      borrowed = radiantBorrow(source, target!, day);
      emit(
        "ability_changed",
        {
          actorId: maid,
          abilityId: borrowed.id,
          kind: borrowed.kind,
          operation: "granted",
          source: borrowed.source,
          sourceDisclosed: true,
          startsOnDay: day,
          expiresAfterDay: day,
          maxUses: null,
        },
        lastRelease,
      );
    }
    emit(
      "eclipse_swallowed",
      {
        actorId: maid,
        day,
        targetId: target,
        roleId: target === null ? null : roster.get(target)!.role,
        abilityId: borrowed?.id ?? null,
      },
      lastRelease,
      [maid],
    );
    if (target !== null)
      emit("eclipse_native_suppressed", { playerId: target, day }, lastRelease, [target]);
  }
  const abilityActors = (kind: RadiantAbility["kind"]) =>
    n.start.flatMap((id) => {
      const a = id === maid ? borrowed : n.before.get(id);
      return a && a.kind === kind && day >= a.startsOnDay && (id === maid || id !== target)
        ? [{ id, a }]
        : [];
    });
  for (const { id, a } of day >= 2 ? abilityActors("shelter") : []) {
    const result = step(
      "radiant_shelter",
      id,
      "cast_shelter",
      ["target_id"],
      (x) =>
        x.target_id === null ||
        (Number.isSafeInteger(x.target_id) &&
          n.start.includes(x.target_id) &&
          x.target_id !== id &&
          !(a.state.lastDay === day - 1 && a.state.lastTarget === x.target_id)),
    );
    if (!result) return facts;
    emit(
      "radiant_shelter_chosen",
      { actorId: id, day, targetId: result.args.target_id, abilityId: a.id },
      lastRelease,
      [id],
    );
  }
  for (const { id, a } of abilityActors("dream").filter(({ id }) =>
    n.start.some((t) => t !== id),
  )) {
    const result = step(
      "dreamer",
      id,
      "dream",
      ["target_id"],
      (x) =>
        Number.isSafeInteger(x.target_id) && n.start.includes(x.target_id) && x.target_id !== id,
    );
    if (!result) return facts;
    emit(
      "dream_applied",
      {
        actorId: id,
        targetId: result.args.target_id,
        day,
        consecutive: a.state.lastDay === day - 1 && a.state.lastTarget === result.args.target_id,
        ...(id === maid ? { abilityId: a.id } : {}),
      },
      lastRelease,
    );
  }
  const wolves = n.start.filter((id) => roster.get(id)!.role === Role.Wolf),
    holders = wolves.length ? wolves : n.start.includes(maid) ? [maid] : [];
  const firstChat = ds.find((d) => d.stage === "wolf_discussion");
  if (wolves.length && !firstChat && cursor === ds.length) return facts;
  const feed = firstChat?.request.context.visible_events ?? [];
  let phaseIndex = -1,
    tacticalIndex = -1;
  for (const [index, event] of feed.entries()) {
    if (
      event.type === "phase_changed" &&
      event.payload.phase === "night" &&
      event.payload.day === day
    )
      phaseIndex = index;
    if (event.type === "wolf_tactical_order") tacticalIndex = index;
  }
  const order =
    tacticalIndex > phaseIndex ? (feed[tacticalIndex]!.payload.order as number[]) : undefined;
  if (wolves.length) {
    check(
      order &&
        equal(
          [...order].sort((a, b) => a - b),
          [...wolves].sort((a, b) => a - b),
        ),
    );
    emit("wolf_tactical_order", { order: [...order] }, lastRelease, holders);
  }
  const ended = new Set<number>();
  for (let round = 1; round <= 3; round++)
    for (const id of order ?? []) {
      if (ended.has(id)) continue;
      const result = step(
        "wolf_discussion",
        id,
        "speak_to_wolves",
        ["text", "end_chat"],
        (x) => typeof x.text === "string" && typeof x.end_chat === "boolean",
      );
      if (!result) return facts;
      check(result.d.turn === round);
      const end = result.args.end_chat;
      emit(
        end ? "wolf_discussion_ended" : "wolf_discussion",
        {
          actorId: id,
          [end ? "reason" : "text"]: sanitizeSpeechText(result.args.text),
          round,
          ...(end ? {} : { endChat: false }),
        },
        lastRelease,
        holders,
      );
      if (end) ended.add(id);
    }
  const tally = new Map<number, number>();
  for (const id of order ?? holders) {
    const result = step(
      "wolf_vote",
      id,
      "kill_vote",
      ["target_id", "abstain"],
      (x) =>
        typeof x.abstain === "boolean" &&
        (x.target_id === null || (Number.isSafeInteger(x.target_id) && x.target_id > 0)) &&
        (x.abstain || (x.target_id !== null && n.start.includes(x.target_id))),
    );
    if (!result) return facts;
    emit(
      "wolf_kill_vote_cast",
      { actorId: id, abstain: result.args.abstain, targetId: result.args.target_id },
      lastRelease,
      holders,
    );
    if (!result.args.abstain)
      tally.set(result.args.target_id, (tally.get(result.args.target_id) ?? 0) + 1);
  }
  const knife = [...tally].sort(([a, x], [b, y]) => y - x || a - b)[0]?.[0] ?? null;
  for (const { id, a } of abilityActors("potion")) {
    if (id === maid && !a.state.heal && !a.state.poison) continue;
    const result = step(
      "witch",
      id,
      "use_potion",
      ["target_id", "potion_type"],
      (x) =>
        Number.isSafeInteger(x.target_id) &&
        x.target_id > 0 &&
        (x.potion_type === "none" ||
          (x.potion_type === "heal" &&
            a.state.heal === 1 &&
            x.target_id !== id &&
            knife === x.target_id &&
            n.start.includes(x.target_id)) ||
          (x.potion_type === "poison" && a.state.poison === 1 && n.start.includes(x.target_id))),
    );
    if (!result) return facts;
    emit(
      result.args.potion_type === "none" ? "witch_potion_skipped" : "witch_potion_used",
      {
        actorId: id,
        targetId: result.args.target_id,
        potionType: result.args.potion_type,
        ...(id === maid ? { abilityId: a.id } : {}),
      },
      lastRelease,
    );
  }
  for (const { id, a } of abilityActors("seer_check")) {
    const result = step(
      "seer",
      id,
      "check_identity",
      ["target_id"],
      (x) => Number.isSafeInteger(x.target_id) && n.start.includes(x.target_id),
    );
    if (!result) return facts;
    const wolf = roster.get(result.args.target_id)!.camp === Camp.Wolf;
    emit(
      "seer_checked",
      {
        actorId: id,
        targetId: result.args.target_id,
        isWerewolf: wolf,
        result: { kind: "camp", camp: wolf ? "wolf" : "good" },
        ...(id === maid ? { abilityId: a.id } : {}),
      },
      lastRelease,
    );
  }
  check(cursor === ds.length);
  return facts;
}

/**
 * 负责归档机制 verifier 的完整固定装配。输入为 envelope／schema 已验证的 reproduction 数据；
 * 输出为原拒绝或全部审计通过，16步调用和第一失败保持原顺序，不提前捕获可替换函数数组。
 * 贵族独立推导出的 audit 在原位置传给恶魔；其原 RedMoon／nativeStocks 子链仍由恶魔 verifier 消费。
 * 本入口不导入 World、生产结算或 checkpoint 写方，不授予行动权限，不改变归档／规则版本准入。
 * 独立 schema／ID／安全读器只确认结构，历史成功、失败前缀与规则推导仍属于各实际 verifier。
 */
import type { ReproductionRecord } from "../../recording/reproduction";
import { validateInitialIdentityRecord } from "./initial-identity";
import { validateWildChildRecord } from "./wild-child";
import { validateLonelyGirlRecord } from "./lonely-girl";
import { validateGhostBrideRecord } from "../../recording/ghost_bride_record";
import { validateAnimalDreamRecord } from "../../recording/animal_dream_record";
import { validateFragrantPairRecord } from "../../recording/fragrant_pair_seer_record";
import { validateNobleSecretBodyRecord } from "../../recording/noble_secret_body_record";
import { validateDemonHunterRecord } from "../../recording/demon_hunter_record";
import { validateScholarMentorRecord } from "./scholar-mentor/validate";
import { validateMistRavenRecord } from "../../recording/mist_raven_record";
import { validateRadiantEclipseRecord } from "../../recording/radiant_eclipse_record";
import { validateTimeConsortRecord } from "./time-consort/validate";
import { validateWolfSorcererRecord } from "./wolf-sorcerer/validate";
import { validateTricksterRecord } from "./trickster/validate";
import { validateMagicianRecord } from "./magician/validate";
import { validateOrderPrinceRecord } from "./order-prince/validate";

export function verifyReproductionMechanisms(result: ReproductionRecord): void {
  validateInitialIdentityRecord(result);
  validateWildChildRecord(result);
  validateLonelyGirlRecord(result);
  validateGhostBrideRecord(result);
  validateAnimalDreamRecord(result);
  validateFragrantPairRecord(result);
  // 传递的是由归档重建的审计数据，不是运行时 owner、原体或死亡提交回执。
  const noble = validateNobleSecretBodyRecord(result);
  validateDemonHunterRecord(result, noble);
  validateScholarMentorRecord(result);
  validateMistRavenRecord(result);
  validateRadiantEclipseRecord(result);
  validateTimeConsortRecord(result);
  validateWolfSorcererRecord(result);
  validateTricksterRecord(result);
  validateMagicianRecord(result);
  validateOrderPrinceRecord(result);
}

/**
 * Scenario tests consume complete Mist/Raven recordings and deliberate copied Tape/checkpoint mutations.
 * Inputs are the original four variants and both locales; handwritten deaths, snake/raven choices, unsealing knowledge and rejection assertions are the independent oracle.
 * The recording driver owns execution and filesystem resources. Mutations affect only detached records, never archived fixture bytes or the original running authority.
 */
import { expect, test } from "bun:test";
import { Camp } from "../../../../src/core";
import { mistRecording } from "../../../support/features/mist-raven/drivers/recording";
import { parseReproductionRecord, type ReproductionRecord } from "../../../../src/recording/reproduction";
import { validateMistRavenRecord } from "../../../../src/recording/mist_raven_record";
for (const variant of ["linked", "saved-dreamer", "protected-heal", "draw"] as const)
  for (const locale of ["en", "zh-CN"] as const)
    test(`Mist/Raven complete independent native ledger and exact Tape replay ${variant}/${locale}`, async () => {
      const r = await mistRecording(variant, locale);
      expect(r.finalized).toBe(true);
      expect(r.checkpoints.at(-1)!.snapshot.result?.winner).toBe(Camp.Good);
      const deaths = r.events
        .filter((e) => e.type === "night_resolved")
        .map((e) => e.payload.deaths);
      expect(deaths).toEqual(
        variant === "protected-heal"
          ? [[], [11], [6, 3, 5]]
          : variant === "saved-dreamer"
            ? [[11], [5], [6]]
            : [[11], [3, 5], [6]],
      );
      const snake = r.events
        .filter((e) => e.type === "alchemist_snake_chosen")
        .map((e) => e.payload.targetId);
      expect(snake).toEqual(variant === "protected-heal" ? [5] : [null, 3]);
      const extra = r.events
        .filter((e) => e.type === "raven_knife_chosen")
        .map((e) => e.payload.targetId);
      expect(extra).toEqual([variant === "saved-dreamer" ? 5 : 3]);
      const known = r.events
        .filter((e) => e.type === "raven_unsealed")
        .map((e) => e.payload.knownTeammateIds);
